amf_object_set_number(&onMetaData, "audiosamplerate", audiosamplerate);
amf_object_set_number(&onMetaData, "audiosamplesize", audiosamplesize);
amf_object_set_boolean(&onMetaData, "stereo", stereo);
amf_object_set_number(&onMetaData, "audiocodecid", audiocodecid);
amf_object_set_number(&onMetaData, "filesize", filesize);
amf_serialize(&onMetaData, (char *)packet.m_body, 0, 256);
