            SharedPreferences.Editor editor = sharedPreferences.edit();
            editor.putString("profile_picture_path", imageFile.getAbsolutePath());
            editor.apply();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

Изображение нужно обрезать до круга после его выбора и перед его отображением на ImageButton. В методе onActivityResult необходимо получить изображение, обрезать его до круга и сохранить в файл. Затем этот файл можно использовать для отображения изображения на ImageButton. Вот как должен выглядеть измененный метод onActivityResult:

```java
@Override
public void onActivityResult(int requestCode, int resultCode, @Nullable Intent data) {
    super.onActivityResult(requestCode, resultCode, data);
    if(requestCode == 1 && resultCode == RESULT_OK && data != null && data.getData() != null) {
        // получение выбранного изображения
        Uri imageUri = data.getData();

        try {
            // конвертация изображения в Bitmap
            Bitmap sourceBitmap = MediaStore.Images.Media.getBitmap(getActivity().getContentResolver(), imageUri);

            // вычисление размера стороны квадрата, который округляется до круга
            int sideLength = Math.min(sourceBitmap.getWidth(), sourceBitmap.getHeight());

            // создание нового Bitmap, который содержит круглое изображение
            Bitmap clippedBitmap = Bitmap.createBitmap(sideLength, sideLength, Bitmap.Config.ARGB_8888);
            Canvas canvas = new Canvas(clippedBitmap);
            BitmapShader shader = new BitmapShader(sourceBitmap, Shader.TileMode.CLAMP, Shader.TileMode.CLAMP);
            Paint paint = new Paint();
            paint.setShader(shader);
            paint.setAntiAlias(true);
            float radius = sideLength / 2f;
            canvas.drawCircle(radius, radius, radius, paint);

            // сохранение круглого изображения в файл
            File storageDir = getActivity().getExternalFilesDir(Environment.DIRECTORY_PICTURES);
            File imageFile = File.createTempFile("profile_picture_", ".jpg", storageDir);
            FileOutputStream out = new FileOutputStream(imageFile);
            clippedBitmap.compress(Bitmap.CompressFormat.JPEG, 100, out);
            out.flush();
            out.close();

            // сохранение пути к файлу в SharedPreferences
            SharedPreferences sharedPreferences = getActivity().getSharedPreferences("myPrefs_profile", Context.MODE_PRIVATE);
            SharedPreferences.Editor editor = sharedPreferences.edit();
            editor.putString("profile_picture_path", imageFile.getAbsolutePath());
            editor.apply();

            // отображение круглого изображения на ImageButton
            ImageButton imageButtonProfile = getActivity().findViewById(R.id.imageButtonProfile);
            imageButtonProfile.setImageBitmap(clippedBitmap);
        } catch (IOException e) {
            e.printStackTrace();
            Toast.makeText(getActivity(), "Failed to open image", Toast.LENGTH_SHORT).show();
        }
    }
}
```

В этом коде мы сначала получаем изображение из выбранного файла и создаем новый Bitmap, который содержит только круглую форму исходного изображения. Затем мы сохраняем круглое изображение в файл и записываем путь к этому файлу в SharedPreferences. И, наконец, мы отображаем круглое изображение на ImageButton. 

Обратите внимание, что этот код также сохраняет круглое изображение в локальном хранилище, чтобы его можно было использовать при следующем запуске приложения.

Если ваша изображение квадратное после его выбора из галереи или камеры, возможно, проблема заключается не только в том, как обрезать изображение до круга, но и в том, как выбрать изображение.

Попробуйте изменить тип MIME в вашем Intent на image/* и удалить атрибут android:outlineProvider="background" из вашего элемента ImageButton. Также убедитесь, что ваша иконка не содержит прозрачную область, которая необходима для обрезки фона вокруг вашего изображения.

Вот как должен выглядеть ваш Intent, чтобы выбрать изображение из галереи:

```java
Intent intent = new Intent(Intent.ACTION_PICK, android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI);
intent.setType("image/*");
startActivityForResult(Intent.createChooser(intent, "Select Picture"), 1);
```

Также проверьте, что ваш Image Button имеет такой вид:

```xml
<ImageButton
    android:id="@+id/imageButtonProfile"
    android:layout_width="156dp"
    android:layout_height="156dp"
    android:layout_gravity="center_horizontal"
    android:layout_marginBottom="16dp"
    android:background="@drawable/circle_background"
    android:padding="24dp"
    android:src="@drawable/baseline_person_add_24" />
```

Обратите внимание, что атрибуты android:clipToOutline и android:outlineProvider удалены, чтобы ImageButton отображался как квадрат, а не как вырезанный круг.

Наконец, если ни одно из этих решений не решает вашу проблему, попробуйте добавить следующий код в ваш метод onActivityResult, чтобы убедиться, что ваше изображение обрезается до круга:

```java
ImageButton imageButtonProfile = getView().findViewById(R.id.imageButtonProfile);
Bitmap sourceBitmap = MediaStore.Images.Media.getBitmap(getActivity().getContentResolver(), imageUri);
Bitmap clipBitmap = clipToCircle(sourceBitmap);
imageButtonProfile.setImageBitmap(clipBitmap);
```

Метод clipToCircle создает Bitmap, который содержит ваше изображение, обрезанное до круга, и может выглядеть так:

```java
private Bitmap clipToCircle(Bitmap source) {
    Bitmap clipped = Bitmap.createBitmap(source.getWidth(), source.getHeight(), Bitmap.Config.ARGB_8888);
    Canvas canvas = new Canvas(clipped);
    Paint paint = new Paint();
    paint.setAntiAlias(true);
    float cx = source.getWidth() * 0.5f;
    float cy = source.getHeight() * 0.5f;
    float radius = Math.min(cx, cy);
    canvas.drawCircle(cx, cy, radius, paint);
    paint.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.SRC_IN));
    canvas.drawBitmap(source, 0, 0, paint);
    return clipped;
}
``` 

