    }

    public void Backpropagate(double reward)
    {
        NumberOfVisits++;
        TotalReward += reward;

        if (Parent != null)
        {
            Parent.Backpropagate(reward);
        }
    }

    public double GetUCTValue(double explorationConstant)
    {
        if (NumberOfVisits == 0)
        {
            return double.MaxValue;
        }

        double exploitationTerm = TotalReward / NumberOfVisits;
        double explorationTerm = explorationConstant * Math.Sqrt(Math.Log(Parent.NumberOfVisits) / NumberOfVisits);
        return exploitationTerm + explorationTerm;
    }
}
