static ssize_t PageFramStat_read(struct file *file, char __user * out, size_t size, loff_t * off) {
	struct page_info *buf = file->private_data;
	ssize_t result = 0;

	if (*off == 0) {
		//获取页面帧信息
		get_page_frame_stat(buf);

		//将内核空间的buf拷贝到用户空间out中
		if (copy_to_user(out, buf, sizeof(struct page_info))) {
			return -EFAULT;
		}

		//更新偏移量
		*off += sizeof(struct page_info);
		result = sizeof(struct page_info);
	}

	return result;
}
