        AM_MEDIA_TYPE* pMediaType = NULL;
        int nMediaTypeIndex = -1;
        bool bMediaTypeFound = false;

        // Retrieve the capture filter's configuration interface
        HRESULT hr = pCapture->FindInterface(
            &PIN_CATEGORY_CAPTURE, &MEDIATYPE_Video, pCamera,
            IID_IAMStreamConfig, (void**)&pConfig
        );

        // Enumerate the capture filter's available media types
        DWORD dwCount = 0, dwSize = 0;
        pConfig->GetNumberOfCapabilities(&dwCount, &dwSize);
        for (DWORD i = 0; i < dwCount; i++) {
            VIDEO_STREAM_CONFIG_CAPS caps;
            AM_MEDIA_TYPE* pmt = NULL;

            // Retrieve the i'th media type
            pConfig->GetStreamCaps(i, &pmt, (BYTE*)&caps);

            // Ignore non-standard media types
            if (pmt->formattype != FORMAT_VideoInfo) {
                FreeMediaType(*pmt);
                continue;
            }

            // Retrieve the media type's width and height
            VIDEOINFOHEADER* pvi = (VIDEOINFOHEADER*)pmt->pbFormat;
            int nWidth = pvi->bmiHeader.biWidth;
            int nHeight = pvi->bmiHeader.biHeight;

            // Check if the media type matches the desired resolution
            if (nWidth == 640 && nHeight == 480) {
                // Select the media type
                pMediaType = pmt;
                nMediaTypeIndex = i;
                bMediaTypeFound = true;
                break;
            }

            FreeMediaType(*pmt);
        }

        // Set the capture filter's media type
        if (bMediaTypeFound) {
            pConfig->SetFormat(pMediaType);

