    MessageBox(hWnd, L"Failed to retrieve IFileSinkFilter interface.", NULL, MB_OK);
    return 0;
}

// Specify the output file name
WCHAR szFileName[MAX_PATH] = {0};
OPENFILENAME ofn = {sizeof(OPENFILENAME)};
ofn.hwndOwner = hWnd;
ofn.lpstrFilter = L"AVI Files (*.avi)\0*.avi\0All Files (*.*)\0*.*\0";
ofn.lpstrFile = szFileName;
ofn.nMaxFile = MAX_PATH;
ofn.Flags = OFN_PATHMUSTEXIST | OFN_OVERWRITEPROMPT;

if (!GetSaveFileName(&ofn)) return 0;

// Specify the output file name to the file writer filter
pFileSink->SetFileName(szFileName, NULL);
```

7. Configure the codec to compress and save the video data into the file:

```cpp
// Retrieve the codec filter's interface
IUnknown* pUnk = NULL;
hr = pCodec->QueryInterface(IID_IUnknown, (void**)&pUnk);

// Create the media type structure for the compressed video
AM_MEDIA_TYPE mt;
ZeroMemory(&mt, sizeof(AM_MEDIA_TYPE));
mt.majortype = MEDIATYPE_Video;
mt.subtype = MEDIASUBTYPE_MJPG;
mt.bFixedSizeSamples = TRUE;
mt.bTemporalCompression = FALSE;
mt.lSampleSize = 0;
mt.formattype = FORMAT_VideoInfo;
mt.cbFormat = sizeof(VIDEOINFOHEADER);

// Specify the compressed video format
VIDEOINFOHEADER* pvi = (VIDEOINFOHEADER*)CoTaskMemAlloc(sizeof(VIDEOINFOHEADER));
ZeroMemory(pvi, sizeof(VIDEOINFOHEADER));
pvi->bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
pvi->bmiHeader.biWidth = 640;
pvi->bmiHeader.biHeight = 480;
pvi->bmiHeader.biPlanes = 1;
pvi->bmiHeader.biBitCount = 24;
pvi->bmiHeader.biCompression = FOURCC_MJPG;
pvi->bmiHeader.biSizeImage = 640 * 480 * 3;
pvi->AvgTimePerFrame = 333333;
mt.pbFormat = (BYTE*)pvi;

// Connect the capture filter to the codec filter
IPin* pCameraOutput = GetPin(pCamera, PINDIR_OUTPUT);
IPin* pCodecInput = GetPin(pCodec, PINDIR_INPUT);
hr = pGraph->ConnectDirect(pCameraOutput, pCodecInput, &mt);

// Connect the codec filter to the file writer filter
IPin* pCodecOutput = GetPin(pCodec, PINDIR_OUTPUT);
IPin* pMuxerInput = GetPin(pMuxer, PINDIR_INPUT);
hr = pGraph->ConnectDirect(pCodecOutput, pMuxerInput, NULL);

pUnk->Release();
```

8. Start the capture filter graph and capture video frames from the camera:

```cpp
// Set the preview window
IVideoWindow* pWindow = NULL;
hr = pGraph->QueryInterface(IID_IVideoWindow, (void**)&pWindow);
pWindow->put_Owner((OAHWND)hWnd);
pWindow->put_WindowStyle(WS_CHILD | WS_CLIPCHILDREN | WS_CLIPSIBLINGS);
pWindow->put_MessageDrain((OAHWND)hWnd);
RECT rc;
GetClientRect(hWnd, &rc);
pWindow->SetWindowPosition(0, 0, rc.right, rc.bottom);
pWindow->put_Visible(TRUE);

// Start the graph
pGraph->QueryInterface(IID_IMediaControl, (void**)&pControl);
pControl->Run();

// Start the message loop
MSG msg;
while (GetMessage(&msg, NULL, 0, 0)) {
    TranslateMessage(&msg);
    DispatchMessage(&msg);

    if (msg.message == WM_QUIT) break;
}

// Stop the graph
pControl->Stop();
pControl->Release();
pWindow->put_Visible(FALSE);
pWindow->put_Owner(NULL);
pWindow->Release();
```

9. Compress and encode each video frame and write it to the file:

```cpp
HRESULT hr;
IMediaSample* pSample;

// Retrieve the codec output pin
IPin* pCodecOutput = GetPin(pCodec, PINDIR_OUTPUT);

// Retrieve the file writer input pin
IPin* pMuxerInput = GetPin(pMuxer, PINDIR_INPUT);

// Retrieve the sample allocator for the codec output pin
IMemAllocator* pAllocator = NULL;
hr = pCodecOutput->QueryInterface(IID_IMemAllocator, (void**)&pAllocator);
hr = pAllocator->SetProperties(NULL);

// Allocate a sample for the codec output pin
pAllocator->GetBuffer(&pSample, NULL, NULL, NULL);

// Copy the video data to the sample
BYTE* pBuffer = NULL;
hr = pSample->GetPointer(&pBuffer);
hr = pSample->SetActualDataLength(dwBufferSize);
CopyMemory(pBuffer, pCaptureBuffer, dwBufferSize);

// Set the sample's media time
REFERENCE_TIME rtStart = 0, rtEnd = 0;
rtEnd = rtStart + pvi->AvgTimePerFrame;
pSample->SetTime(&rtStart, &rtEnd);

// Send the sample to the codec input pin
hr = pCodecOutput->QueryInterface(IID_IMediaSampleFilter, (void**)&pFilter);
hr = pCapture->RenderStream(&PIN_CATEGORY_CAPTURE, &MEDIATYPE_Video, pCamera, pCodec, NULL);

// Send the sample to the file writer input pin
hr = pMuxerInput->QueryInterface(IID_IMediaSampleFilter, (void**)&pFilter);
hr = pFilter->SendSample(pSample);
pSample->Release();

pAllocator->Release();
pCodecOutput->Release();
pMuxerInput->Release();
```

