        bool bx = 0, by = 0, bfill = 0;
        for (int i = 0; i < num_of_coordinates; i++) {
            if (bx) X_generated[i] = X_average_coordinates[i] - (rand() % X_plus_minus[i]);
            else X_generated[i] = X_average_coordinates[i] + (rand() % X_plus_minus[i]);
            if (by) Y_generated[i] = Y_average_coordinates[i] - (rand() % Y_plus_minus[i]);
            else Y_generated[i] = Y_average_coordinates[i] + (rand() % Y_plus_minus[i]);
            bx = rand() % 2;
            by = rand() % 2;
        }
        bfill = rand() % 2;
        if (bfill) generated_fill = average_fill - rand() % plus_minus_fill;
        else generated_fill = average_fill + rand() % plus_minus_fill;
    }
};

// Function to load the BMP image and extract the model data
bool loadBmpModel(LPCTSTR fileName, model& mdl) {
    HBITMAP hBmp = (HBITMAP)LoadImage(NULL, fileName, IMAGE_BITMAP, 0, 0, LR_LOADFROMFILE | LR_CREATEDIBSECTION);
    if (!hBmp) return false;

    BITMAP bmp = { 0 };
    GetObject(hBmp, sizeof(bmp), &bmp);

    int nPixels = bmp.bmWidth * bmp.bmHeight;
    vector<int> X_coords, Y_coords, Fill_vals;
    X_coords.reserve(nPixels);
    Y_coords.reserve(nPixels);
    Fill_vals.reserve(nPixels);

    for (int j = bmp.bmHeight - 1; j >= 0; j--) {
        for (int i = 0; i < bmp.bmWidth; i++) {
            COLORREF pixel = ((COLORREF*)bmp.bmBits)[j * bmp.bmWidth + i];
            if (pixel != 0xFFFFFF) { // ignore the white background color
                X_coords.push_back(i);
                Y_coords.push_back(j);
                Fill_vals.push_back(pixel);
            }
        }
    }

    mdl.num_of_coordinates = X_coords.size();
    mdl.X_average_coordinates = new int[mdl.num_of_coordinates];
    mdl.Y_average_coordinates = new int[mdl.num_of_coordinates];
    mdl.X_plus_minus = new int[mdl.num_of_coordinates];
    mdl.Y_plus_minus = new int[mdl.num_of_coordinates];

    // Calculate the average X, average Y and fill value of the model
    double sumX = accumulate(X_coords.begin(), X_coords.end(), 0);
    double sumY = accumulate(Y_coords.begin(), Y_coords.end(), 0);
    double sumFill = accumulate(Fill_vals.begin(), Fill_vals.end(), 0);
    mdl.average_fill = static_cast<int>(sumFill / mdl.num_of_coordinates);

    for (int i = 0; i < mdl.num_of_coordinates; i++) {
        mdl.X_average_coordinates[i] = static_cast<int>(sumX / mdl.num_of_coordinates);
        mdl.Y_average_coordinates[i] = static_cast<int>(sumY / mdl.num_of_coordinates);
    }

    sort(X_coords.begin(), X_coords.end());
    sort(Y_coords.begin(), Y_coords.end());

    int deltaX = X_coords.back() - X_coords.front();
    int deltaY = Y_coords.back() - Y_coords.front();

    for (int i = 0; i < mdl.num_of_coordinates; i++) {
        mdl.X_plus_minus[i] = deltaX;
        mdl.Y_plus_minus[i] = deltaY;
    }

    // Clean up
    DeleteObject(hBmp);

    return true;
}

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    // Initialize random seed
    srand(static_cast<unsigned int>(time(nullptr)));

    // Create a vector to store all the BMP file names
    vector<wstring> bmpFiles;
    WIN32_FIND_DATA fd;
    HANDLE hFind = FindFirstFile(L"*.bmp", &fd);
    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            if (!(fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
                wstring fileName = fd.cFileName;
                bmpFiles.push_back(fileName);
            }
        } while (FindNextFile(hFind, &fd));
        FindClose(hFind);
    }

    if (bmpFiles.empty()) return 0;

    // Create an array of model structs
    const int numModels = 1000;
    model models[numModels];

    // Load and extract model data from the BMP images
    int numLoaded = 0;
    for (auto& fileName : bmpFiles) {
        if (!loadBmpModel(fileName.c_str(), models[numLoaded])) {
            cerr << "Failed to load BMP file: " << fileName << endl;
            continue;
        }

        // Generate coordinates and fill value for the model
        models[numLoaded].generate();

        numLoaded++;
        if (numLoaded == numModels) break;
    }

    // Calculate the average X, average Y and fill value of the model across all the loaded BMP images
    double sumX = 0, sumY = 0, sumFill = 0;
    for (int i = 0; i < numLoaded; i++) {
        sumX += accumulate(models[i].X_average_coordinates, models[i].X_average_coordinates + models[i].num_of_coordinates, 0);
        sumY += accumulate(models[i].Y_average_coordinates, models[i].Y_average_coordinates + models[i].num_of_coordinates, 0);
        sumFill += models[i].average_fill;
    }

    int avgX = static_cast<int>(sumX / (numLoaded * models[0].num_of_coordinates));
    int avgY = static_cast<int>(sumY / (numLoaded * models[0].num_of_coordinates));
