bool loadBmpModel(LPCTSTR fileName, simple_model& mdl) {
    HBITMAP hBmp = (HBITMAP)LoadImage(NULL, fileName, IMAGE_BITMAP, 0, 0, LR_LOADFROMFILE | LR_CREATEDIBSECTION);
    if (!hBmp) return false;

    BITMAP bmp = { 0 };
    GetObject(hBmp, sizeof(bmp), &bmp);

    int nPixels = bmp.bmWidth * bmp.bmHeight;
    vector<int> X_coords, Y_coords, Fill_vals;
    X_coords.reserve(nPixels);
    Y_coords.reserve(nPixels);
    Fill_vals.reserve(nPixels);

    for (int j = bmp.bmHeight - 1; j >= 0; j--) {
        for (int i = 0; i < bmp.bmWidth; i++) {
            COLORREF pixel = ((COLORREF*)bmp.bmBits)[j * bmp.bmWidth + i];
            if (pixel != 0xFFFFFF) { // ignore the white background color
                X_coords.push_back(i);
                Y_coords.push_back(j);
                Fill_vals.push_back(pixel);
            }
        }
    }

    mdl.num_of_coordinatesX = X_coords.size();
    mdl.num_of_coordinatesY = Y_coords.size();
    mdl.X_coordinates = new int[mdl.num_of_coordinatesX];
    mdl.Y_coordinates = new int[mdl.num_of_coordinatesY];

    double sumX = accumulate(X_coords.begin(), X_coords.end(), 0);
    double sumY = accumulate(Y_coords.begin(), Y_coords.end(), 0);
    double sumFill = accumulate(Fill_vals.begin(), Fill_vals.end(), 0);
    mdl.fill = static_cast<int>(sumFill / mdl.num_of_coordinatesX);

    for (int i = 0; i < mdl.num_of_coordinatesX; i++) {
        mdl.X_coordinates[i] = X_coords[i];
    }
    for (int i = 0; i < mdl.num_of_coordinatesY; i++) {
        mdl.Y_coordinates[i] = Y_coords[i];
    }

    sort(X_coords.begin(), X_coords.end());
    sort(Y_coords.begin(), Y_coords.end());

    int deltaX = X_coords.back() - X_coords.front();
    int deltaY = Y_coords.back() - Y_coords.front();

    delete[] bmp.bmBits;
    DeleteObject(hBmp);

    return true;
}

