import kotlinx.coroutines.GlobalScope
import kotlinx.coroutines.async
import kotlinx.coroutines.delay
import kotlinx.coroutines.runBlocking

private fun now(): Long {
    return System.currentTimeMillis()
}

fun log(msg: Any) {
    println("${now()} : $msg")
}

suspend fun longComputation(): Int {
    delay(1000)
    return 43
}

fun processInt(x: Int): String {
    return "The number is $x"
}

fun main() {
    log("Start")
    // Use async to start a coroutine for longComputation
    // The result is wrapped in a Deferred<Int>
    val deferredResult = GlobalScope.async { longComputation() }
    log("Long computation coroutine started")

    // Coroutine for mapping the result of 'longComputation' to a String
    GlobalScope.async {
        log("Mapping the result of long computation to a String")
        val stringResult = processInt(deferredResult.await())
        log(stringResult)
    }
    log("Done")

    // Keep the main function alive for the coroutines to complete
    // This should be replaced with a more appropriate
    // way of waiting for coroutines in real-world scenarios
    runBlocking {
        delay(2000)
    }
}
