Для этого мы можем добавить дополнительную проверку при генерации позиции 'T', чтобы она не генерировалась рядом с 'S'. Затем, в зависимости от 30%-ного шанса, будем сознательно генерировать 'T' рядом с 'S' или генерировать 'T' в другой части сетки. Итак, попробуем обновить функцию `generateGrid()`:

```cpp
vector<vector<char>> generateGrid(int n, int m)
{
    vector<vector<char>> grid(n, vector<char>(m, '.'));

    int num_cells = n * m;
    int num_obstacles = num_cells / 4;

    int s_row, s_col, t_row, t_col;
    do {
        s_row = rand() % n;
        s_col = rand() % m;
    } while (grid[s_row][s_col] != '.');

    grid[s_row][s_col] = 'S';

    // Массив для хранения соседних клеток 'S'
    vector<pair<int, int>> neighbors;

    // Добавьте соседние клетки S в массив neighbours
    int dir[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    for (int i = 0; i < 4; i++) {
        int newRow = s_row + dir[i][0], newCol = s_col + dir[i][1];
        if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < m) {
            neighbors.emplace_back(newRow, newCol);
        }
    }

    do {
        // Мы считаем 30% вероятность спавна T рядом с S
        bool spawn_near_s = (rand() % 100) < 30;
        if (spawn_near_s && !neighbors.empty()) {
            int idx = rand() % neighbors.size();
            t_row = neighbors[idx].first;
            t_col = neighbors[idx].second;
        }
        else {
            t_row = rand() % n;
            t_col = rand() % m;
        }
    } while (grid[t_row][t_col] != '.');

    grid[t_row][t_col] = 'T';

    for (int i = 0; i < num_obstacles; i++) {
        int row, col;
        do {
            row = rand() % n;
            col = rand() % m;
        } while (grid[row][col] != '.');

        grid[row][col] = '#';
    }

    return grid;
}
```

