Apologies for the confusion. The poolSizes variable should be declared and initialized within the CreateDescriptorPool() function. It should be an array of VkDescriptorPoolSize structs that represents the types of descriptors and the number of descriptors that will be available in the descriptor pool. Here's the fixed version of the CreateDescriptorPool() function:

Renderer.cpp:
```cpp
VkDescriptorPool Renderer::CreateDescriptorPool(uint32_t maxSets) {
    VkDescriptorPoolSize poolSize{};
    poolSize.type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
    poolSize.descriptorCount = maxSets;

    VkDescriptorPoolCreateInfo poolInfo{};
    poolInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    poolInfo.poolSizeCount = 1;
    poolInfo.pPoolSizes = &poolSize;
    poolInfo.maxSets = maxSets;

    VkDescriptorPool descriptorPool;
    if (vkCreateDescriptorPool(device, &poolInfo, nullptr, &descriptorPool) != VK_SUCCESS) {
        throw std::runtime_error("Failed to create descriptor pool!");
    }

    return descriptorPool;
}
```

