// ...

// Define custom deleters for each Vulkan object
struct ImageDeleter
{
    VkDevice device;

    void operator()(VkImage image)
    {
        vkDestroyImage(device, image, nullptr);
    }
};

struct ImageMemoryDeleter
{
    VkDevice device;

    void operator()(VkDeviceMemory imageMemory)
    {
        vkFreeMemory(device, imageMemory, nullptr);
    }
};

struct ImageViewDeleter
{
    VkDevice device;

    void operator()(VkImageView imageView)
    {
        vkDestroyImageView(device, imageView, nullptr);
    }
};

struct SamplerDeleter
{
    VkDevice device;

    void operator()(VkSampler sampler)
    {
        vkDestroySampler(device, sampler, nullptr);
    }
};

// ...

class Texture
{
