private:
    // Replace Vulkan objects with std::shared_ptr
    std::shared_ptr<VkImage_T> image;
    std::shared_ptr<VkDeviceMemory_T> imageMemory;
    std::shared_ptr<VkImageView_T> imageView;
    std::shared_ptr<VkSampler_T> sampler;

    // ...
};

```

Now, change the `Texture` class methods to use `std::shared_ptr`. Update the `Initialize`, `Cleanup`, and `CreateImage`, `CreateImageView`, and `CreateSampler` methods accordingly.

Texture.cpp:

```cpp
// ...

void Texture::Initialize(/* ... */)
{
    // ...

    // When creating the Vulkan objects, use std::shared_ptr with custom deleters
    image = std::shared_ptr<VkImage_T>(new VkImage(VK_NULL_HANDLE), ImageDeleter { device });
    imageMemory = std::shared_ptr<VkDeviceMemory_T>(new VkDeviceMemory(VK_NULL_HANDLE), ImageMemoryDeleter { device });
    imageView = std::shared_ptr<VkImageView_T>(new VkImageView(VK_NULL_HANDLE), ImageViewDeleter { device });
    sampler = std::shared_ptr<VkSampler_T>(new VkSampler(VK_NULL_HANDLE), SamplerDeleter { device });

    // ...
}

void Texture::Cleanup()
{
    // No need to manually destroy Vulkan objects, as std::shared_ptr will handle cleanup
    // Make sure to reset the shared_ptrs, though
    image.reset();
    imageMemory.reset();
    imageView.reset();
    sampler.reset();
}

// ... (Modify CreateImage, CreateImageView, and CreateSampler methods similarly)

```

With these changes, you can use `std::shared_ptr` for your Vulkan objects, allowing multiple objects to share ownership and automatically cleaning up when no longer needed. You can apply the same method for other classes and Vulkan objects used in the project.

