        case Minus:
            return args[0] - args[1], nil
        case Multiply:
            return args[0] * args[1], nil
        case Divide:
            return args[0] / args[1], nil
        case Power:
            return math.Pow(args[0], args[1]), nil
        case Sqrt:
            return math.Sqrt(args[0]), nil
        case Root:
            return math.Pow(args[1], 1.0 / args[0]), nil
        case Sin:
            return math.Sin(DegressToRadian(args[0])), nil
        case Cos:
            return math.Cos(DegressToRadian(args[0])), nil
        case Tan:
            return math.Tan(DegressToRadian(args[0])), nil
        case Cot:
            return 1 / math.Tan(DegressToRadian(args[0])), nil
        default:
            return 0, fmt.Errorf("Неизвестная операция: %v", op.Value)
        }
    }

    var numStack []float64
    var opStack []Token

    handleOperation := func() error {
        op := opStack[len(opStack)-1]
        opStack = opStack[:len(opStack)-1]

        var args []float64
        if op.Type == Sqrt || op.Type == Sin || op.Type == Cos || op.Type == Tan || op.Type == Cot {
            args = []float64{numStack[len(numStack)-1]}
            numStack = numStack[:len(numStack)-1]
        } else if op.Type == Root {
            args = []float64{numStack[len(numStack)-2], numStack[len(numStack)-1]}
            numStack = numStack[:len(numStack)-2]
        } else {
            args = []float64{numStack[len(numStack)-2], numStack[len(numStack)-1]}
            numStack = numStack[:len(numStack)-2]
        }

        res, err := applyOperation(op, args...)
        if err != nil {
            return err
        }

        numStack = append(numStack, res)
        return nil
    }

    for _, token := range tokens {
        switch token.Type {
        case Number:
            val, err := strconv.ParseFloat(token.Value, 64)
            if err != nil {
                return 0, err
            }
            numStack = append(numStack, val)
        case Variable:
            val, ok := vars[token.Value]
            if !ok {
                return 0, fmt.Errorf("Отсутствует значение для переменной: %v", token.Value)
            }
            numStack = append(numStack, val)
        case Plus, Minus, Multiply, Divide, Power, Sqrt, Sin, Cos, Tan, Cot, Root:
            for len(opStack) > 0 && precedence(token.Type) <= precedence(opStack[len(opStack)-1].Type) {
                if err := handleOperation(); err != nil {
                    return 0, err
                }
            }
            opStack = append(opStack, token)
        case LeftParen:
            opStack = append(opStack, token)
        case RightParen:
            for len(opStack) > 0 && opStack[len(opStack)-1].Type != LeftParen {
                if err := handleOperation(); err != nil {
                    return 0, err
                }
            }
            if len(opStack) > 0 && opStack[len(opStack)-1].Type == LeftParen {
                opStack = opStack[:len(opStack)-1]
            }
        }
    }

    for len(opStack) > 0 {
        if err := handleOperation(); err != nil {
            return 0, err
        }
    }

    if len(numStack) != 1 {
        return 0, fmt.Errorf("Неверное количество аргументов")
    }

    return numStack[0], nil
}
``

Для переписывания интерпретатора можно предложить следующий шаблон:

1. Лексер: сканирует выражение и создает список токенов.
2. Парсер: просматривает список токенов, созданный лексером, и создает абстрактное синтаксическое дерево (AST).
3. Вычислитель: вычисляет результат, обходя AST.

Определим типы для наших узлов AST:

```go
type Node interface {
	Eval() (float64, error)
}

type NumberNode struct {
	Value float64
}

type VariableNode struct {
	Name string
}

type UnaryOpNode struct {
	Op    TokenType
	Child Node
}

type BinaryOpNode struct {
	Op  TokenType
	LHS Node
	RHS Node
}

type FuncCallNode struct {
	FuncName string
	Args     []Node
}
```

Этот код добавляет интерфейс `Eval` в узлы синтаксического дерева, чтобы вычислитель мог использовать этот интерфейс для вычисления результата. Здесь также определяются несколько структур для представления разных видов узлов, таких как `NumberNode`, `VariableNode`, `UnaryOpNode`, `BinaryOpNode` и `FuncCallNode`, которые соответствуют различным операциям и значениям вашего выражения.

Далее, давайте реализуем некоторые методы для наших узлов:

```go
func (n *NumberNode) Eval() (float64, error) {
	return n.Value, nil
}

func (n *VariableNode) Eval(variables map[string]float64) (float64, error) {
	value, ok := variables[n.Name]
	if !ok {
		return 0, fmt.Errorf("Неизвестное значение переменной: %v", n.Name)
	}
	return value, nil
}

func (n *UnaryOpNode) Eval(variables map[string]float64) (float64, error) {
	childValue, err := n.Child.Eval(variables)
	if err != nil {
		return 0, err
	}

	switch n.Op {
	case Plus:
		return childValue, nil
	case Minus:
		return -childValue, nil
	default:
		return 0, fmt.Errorf("Неизвестная унарная операция: %v", n.Op)
	}
}

func (n *BinaryOpNode) Eval(variables map[string]float64) (float64, error) {
	lhs, err := n.LHS.Eval(variables)
	if err != nil {
		return 0, err
	}

	rhs, err := n.RHS.Eval(variables)
	if err != nil {
		return 0, err
	}

	switch n.Op {
	case Plus:
		return lhs + rhs, nil
	case Minus:
		return lhs - rhs, nil
	case Multiply:
		return lhs * rhs, nil
	case Divide:
		return lhs / rhs, nil
	case Power:
		return math.Pow(lhs, rhs), nil
	default:
		return 0, fmt.Errorf("Неизвестная бинарная операция: %v", n.Op)
	}
}

func (n *FuncCallNode) Eval(variables map[string]float64) (float64, error) {
	args := make([]float64, len(n.Args))
	for i, arg := range n.Args {
		result, err := arg.Eval(variables)
		if err != nil {
			return 0, err
		}
		args[i] = result
	}

	switch n.FuncName {
	case "sin":
		return math.Sin(args[0]), nil
	case "cos":
		return math.Cos(args[0]), nil
	case "tan":
		return math.Tan(args[0]), nil
	case "cot":
		return 1 / math.Tan(args[0]), nil
	case "sqrt":
		return math.Sqrt(args[0]), nil
	case "root":
		return math.Pow(args[1], 1.0/args[0]), nil
	default:
		return 0, fmt.Errorf("Неизвестная функция: %v", n.FuncName)
	}
}
```

Примечание: Некоторые методы `Eval` получили дополнительный аргумент `variables`, который передается из `eval` для предоставления значений переменных.

Теперь давайте перепишем функцию `eval`, чтобы выполнять вычисления, вызывая методы `Eval` узлов AST:

```go
func eval(root Node, variableMaps ...map[string]float64) (float64, error) {
	variables := make(map[string]float64)
	for _, variableMap := range variableMaps {
		for key, value := range variableMap {
			variables[key] = value
		}
	}
	return root.Eval(variables)
}
```

