document.addEventListener("DOMContentLoaded", function () {
  const container = document.getElementById("editableContainer");
  const data = getDataFromContainer();

  function getDataFromContainer() {
    const data = [];
    for (const item of container.children) {
      data.push(item.innerText);
    }
    return data;
  }

  function createVirtualDOM(data) {
    const newContainer = document.createElement("div");

    data.forEach((itemData, index) => {
      const item = document.createElement(container.children[index].nodeName);
      const input = document.createElement("textarea");
      input.innerText = itemData;
      input.addEventListener("input", () => {
        data[index] = input.value;
        updateRealContainer(data);
      });

      item.appendChild(input);
      newContainer.appendChild(item);
    });

    return newContainer;
  }

  function updateRealContainer(data) {
    for (let i = 0; i < container.children.length; i++) {
      container.children[i].innerText = data[i];
    }
  }

  const virtualDOM = createVirtualDOM(data);
  container.innerHTML = virtualDOM.innerHTML;
