                }
                temp1 = temp1.next;
                temp2 = temp2.next;
            }
        }

        while (temp1 != null) {
            result.insert(temp1.coefficient, temp1.power);
            temp1 = temp1.next;
        }

        while (temp2 != null) {
            result.insert(-temp2.coefficient, temp2.power);
            temp2 = temp2.next;
        }

        return result;
    }

