    Node head;

    void insert(int coefficient, int power) {
        Node newNode = new Node(coefficient, power);

        if (head == null) {
            head = newNode;
            return;
        }

        Node current = head;
        Node previous = null;

        while (current != null && current.power > power) {
            previous = current;
            current = current.next;
        }

        if (current != null && current.power == power) {
            current.coefficient += coefficient;
            return;
        }

        if (previous == null) {
            newNode.next = head;
            head = newNode;
        } else {
            newNode.next = current;
            previous.next = newNode;
        }
    }

    void print() {
        Node temp = head;

        while (temp != null) {
            System.out.print(temp.coefficient + "x^" + temp.power);

            if (temp.next != null) {
                System.out.print(" + ");
            }

            temp = temp.next;
        }

        System.out.println();
    }
}

class Node {
    int coefficient;
    int power;
    Node next;

    Node(int coefficient, int power) {
        this.coefficient = coefficient;
        this.power = power;
    }
}
