<< cars[i].mileage << endl
<< cars[i].last_service.day << endl
<< cars[i].last_service.month << endl
<< cars[i].last_service.year << endl;
}

output_file.close();
}

void free_memory(car *cars, int n) {
for (int i = 0; i < n; i++) {
delete[] cars[i].brand;
delete[] cars[i].owner.name;
delete[] cars[i].owner.surname;
delete[] cars[i].owner.patronymic;
delete[] cars[i].last_service.month;
}
}

