function read_file(sn,tn) {
    const s = cv.imread('source/'+sn+'.bmp');
    s.cvtColor(cv.COLOR_BGR2LAB);
    const t = cv.imread('target/'+tn+'.bmp');
    t.cvtColor(cv.COLOR_BGR2LAB);
