}

function get_mean_and_std(x) {
    const x_mean = x.mean();
    const x_std = x.std();
    return [x_mean, x_std];
}

function color_transfer() {
    const sources = ['s1','s2','s3','s4','s5','s6'];
    const targets = ['t1','t2','t3','t4','t5','t6'];

    for (let n = 0; n < sources.length; n++) {
        console.log("Converting picture"+ (n+1) +"...");
        const [s, t] = read_file(sources[n], targets[n]);
        const [s_mean, s_std] = get_mean_and_std(s);
        const [t_mean, t_std] = get_mean_and_std(t);

        const height = s.rows;
        const width = s.cols;
        const channels = s.channels;

        for (let i = 0; i < height; i++) {
            for (let j = 0; j < width; j++) {
                for (let k = 0; k < channels; k++) {
                    let x = s.at(i, j)[k];
                    x = ((x - s_mean[k]) * (t_std[k] / s_std[k])) + t_mean[k];
                    x = Math.round(x);
                    x = x < 0 ? 0 : x;
                    x = x > 255 ? 255 : x;
                    let pixel = s.at(i, j);
                    pixel[k] = x;
                    s.set(i, j, pixel);
                }
            }
        }

        s.cvtColor(cv.COLOR_LAB2BGR);
        cv.imwrite('result/r' + (n + 1) + '.bmp', s);
    }
}

