```java
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

class Address {
    String city;

    Address(String city) {
        this.city = city;
    }

    String getCity() {
        return city;
    }
}

class Employee {
    String firstName;
    String lastName;
    Address address;

    Employee(String firstName, String lastName, Address address) {
        this.firstName = firstName;
        this.lastName = lastName;
        this.address = address;
    }

    String getLastName() {
        return lastName;
    }

    Address getAddress() {
        return address;
    }
}

public class Main {
    public static void main(String[] args) {
        List<Employee> employees = new ArrayList<>();
        employees.add(new Employee("John", "Doe", new Address("Mumbai")));
        employees.add(new Employee("Jane", "Doe", new Address("Mumbai")));
        employees.add(new Employee("Tom", "Smith", new Address("Mumbai")));
        employees.add(new Employee("Jerry", "Brown", new Address("New York")));
        employees.add(new Employee("Emma", "Watson", new Address("London")));

        List<String> uniqueLastNamesInMumbai = employees.stream()
                .filter(employee -> "Mumbai".equalsIgnoreCase(employee.getAddress().getCity()))
                .map(Employee::getLastName)
                .distinct()
                .limit(2)
                .collect(Collectors.toList());

