        await this.clickLocaleButton();
        await this.getRULocaleRadio().click();
        return this;
    }

    // Переключить локализацию на "EN"
    async switchENLocale() {
        await this.clickLocaleButton();
        await this.getENLocaleRadio().click();
        return this;
    }

