   @Autowired
   private EntityManager entityManager;

   public List<GoodsCatalog> getAllCatalogs() {
       TypedQuery<GoodsCatalog> query = entityManager.createQuery(
           "SELECT g FROM GoodsCatalog g", GoodsCatalog.class);
       List<GoodsCatalog> allCatalogs = query.getResultList();

       // Set treePathName for each catalog
       for (GoodsCatalog catalog : allCatalogs) {
           if (catalog.getParentId().equals("0")) {
               catalog.setTreePathName(catalog.getName());
           } else {
               String path = getParentTreePath(catalog, allCatalogs) + " -> " + catalog.getName();
               catalog.setTreePathName(path);
           }
       }

       return allCatalogs;
   }

   private String getParentTreePath(GoodsCatalog catalog, List<GoodsCatalog> allCatalogs) {
