    int i, j;
    for (i = 0; i < rows; i++) {
        matrix[i] = malloc(rows * sizeof(double));
        for (j = 0; j < rows; j++) {
            if (i == j) {
                matrix[i][j] = array[i];
            } else {
                matrix[i][j] = 0.0;
            }
        }
    }
    return matrix;
}

