function processCellsInRange() {

  // Retrieves the active Spreadsheet and stores it in the variable 'ss'
  var ss = SpreadsheetApp.getActiveSpreadsheet();

  // Retrieves the active sheet (the currently visible sheet) and stores it in the variable 'sheet'
  var sheet = ss.getActiveSheet();

  // Retrieves the range C10:C26 on the active sheet and stores it in the variable 'range'
  var range = sheet.getRange("C10:C26");

  // Retrieves the last row number with content in the specified range ('C10:C26') and stores it in the variable 'lastRowInRange'
  var lastRowInRange = range.getLastRow();

  // Begins a for loop that iterates through the rows from the starting index (10) until the last row with content in the range
  for (var i = 10; i <= lastRowInRange; i++) {

    // Retrieves the column number of the last cell with content in the current row and stores it in the variable 'lastCellInRow'
    var lastCellInRow = sheet.getRange("1:" + i).getLastColumn();

    // Retrieves the value of the last cell in the current row using the row and column number and stores it in the variable 'lastCellValue'
    var lastCellValue = sheet.getRange(i, lastCellInRow).getValue();

    // Checks if the last cell value in the row ends with "day" OR "ime" and if so, skips the further actions for this row
    if (lastCellValue.endsWith('day') || lastCellValue.endsWith('ime')) {
      continue;
    }

    // Retrieves the value of the cell in column C of the current row and stores it in the variable 'cell'
    var cell = sheet.getRange("C" + i);

    // Retrieves the value of the cell in column C of the current row and stores it in the variable 'currentValue'
    var currentValue = cell.getValue();

    // Retrieves the value of the cell one column to the right of the current cell and stores it in the variable 'nextCell'
    var nextCell = sheet.getRange(sheet.getRange("C" + i).offset(0,1).getA1Notation());

