private fun readItemsFromXml(xmlString: String) {
    val factory = XmlPullParserFactory.newInstance()
    val parser = factory.newPullParser()
    parser.setInput(StringReader(xmlString))
    var eventType = parser.eventType
    var itemId: String? = null
    while (eventType != XmlPullParser.END_DOCUMENT) {
        when (eventType) {
            XmlPullParser.START_TAG -> {
                if (parser.name == "item") {
                    // This is an "item" tag, so read its "id" property
                    itemId = parser.getAttributeValue(null, "id")
                }
            }
            XmlPullParser.END_TAG -> {
                if (parser.name == "item") {
                    // We have finished reading one "item" tag, so do something with its "id" property
                    handleItemId(itemId)
                    itemId = null
                }
            }
        }
        eventType = parser.next()
    }
}

private fun handleItemId(itemId: String?) {
    // Do something with the itemId (e.g. add it to a list)
    if (itemId != null) {
        Log.d(TAG, "Found item with id: $itemId")
    }
}
```

