   // Set the timeframe, symbol and apply the RSI indicator
   int timeframe = Period();
   string symbol = Symbol();
   int rsi_handle = iRSI(symbol, timeframe, RSI_Period, PRICE_CLOSE);

   // Buffers for RSI values
   double rsi_values[];
   ArraySetAsSeries(rsi_values, true);
   CopyBuffer(rsi_handle, 0, 0, RSI_Period + 4, rsi_values);

   // Check for divergence
   int last_bar = 4;

   // Bullish Divergence
   bool bullish_div = rsi_values[last_bar] < RSI_Level_Oversold
                      && rsi_values[last_bar - 2] > rsi_values[last_bar]
                      && Low[last_bar - 2] < Low[last_bar]
                      && rsi_values[0] < RSI_Level_Oversold;

   if (bullish_div)
     {
      ObjectCreate("BullishArrow", OBJ_ARROW, 0, Time[last_bar], Low[last_bar] - 10 * Point);
      ObjectSet("BullishArrow", OBJPROP_ARROWCODE, 233); // Up arrow
      ObjectSet("BullishArrow", OBJPROP_COLOR, clrGreen);
     }

   // Bearish Divergence
   bool bearish_div = rsi_values[last_bar] > RSI_Level_Overbought
                      && rsi_values[last_bar - 2] < rsi_values[last_bar]
                      && High[last_bar - 2] > High[last_bar]
                      && rsi_values[0] > RSI_Level_Overbought;

   if (bearish_div)
     {
      ObjectCreate("BearishArrow", OBJ_ARROW, 0, Time[last_bar], High[last_bar] + 10 * Point);
      ObjectSet("BearishArrow", OBJPROP_ARROWCODE, 234); // Down arrow
      ObjectSet("BearishArrow", OBJPROP_COLOR, clrRed);
     }
  }
