using UnityEngine;

public class SaveSystem : MonoBehaviour
{
    public void SaveInventories()
    {
        string json = JsonUtility.ToJson(InventoriesManager.Instance.Inventories);
        PlayerPrefs.SetString("Inventories", json);
        PlayerPrefs.Save();
    }

    public void LoadInventories()
    {
        if (PlayerPrefs.HasKey("Inventories"))
        {
