for(Card card: this.cardsOnHand) {
total+=card.getValue();
}
return total;
}


public Card getLastCard() {
return this.cardsOnHand.get(this.cardsOnHand.size()-1);
}

public void clearCardsOnHand() {
this.cardsOnHand.clear();
}

