1. In the `ScreenerPage`, create a state to hold the array of coin data.
```javascript
const [coinsData, setCoinsData] = useState([]);
```

2. Create the `updateCoinsData` callback function:
```javascript
const updateCoinsData = useCallback((symbol, coinData) => {
  setCoinsData((prevCoinsData) => {
    const newCoinsData = [...prevCoinsData];
    const existingIndex = newCoinsData.findIndex((data) => data.symbol === symbol);

    if (existingIndex !== -1) {
      newCoinsData[existingIndex] = {symbol, ...coinData};
    } else {
      newCoinsData.push({symbol, ...coinData});
    }

    return newCoinsData;
  });
}, []);
```

3. Pass the `updateCoinsData` callback to the `ScreenerSymbol` component.
```javascript
<ScreenerSymbol
  key={symbol}
  // other props
  updateCoinsData={updateCoinsData}
/>
```

4. In the `ScreenerSymbol` component, invoke the `updateCoinsData` callback with the `symbol` and `coin` data when the data is available.
```javascript
useEffect(() => {
  if (coin) {
    updateCoinsData(symbol, coin);
  }
}, [coin]);
```

