const sortCoins = (sortBy, order) => {
  setCoinsData((prevCoinsData) => {
    const sortedData = [...prevCoinsData].sort((a, b) => {
      if (order === "asc") {
        return a[sortBy] - b[sortBy];
      }
      return b[sortBy] - a[sortBy];
    });

    return sortedData;
  });
};
```

