export interface ScreenerSymbolProps {
    symbol: string
    activeSymbol: string
    setActiveSymbol: (symbol: string) => void
    connectedSymbols: string[]
    setConnectedSymbols: Dispatch<SetStateAction<string[]>>
    symbolsFilters: string
    handleCoinData: any
}
const ScreenerSymbol = ({symbol, activeSymbol, setActiveSymbol, connectedSymbols, setConnectedSymbols, symbolsFilters, handleCoinData}: ScreenerSymbolProps) => {

  const coin = useSelector((state: AppState) => state.binancePrice.futures24h[symbol.toUpperCase()]);
  const {futures24hSubscribe, futures24hUnSubscribe} = useBinanceWsProvider();

  useEffect(() => {
    if(!coin) return;
    handleCoinData(coin);
  }, [coin, handleCoinData]);

  useEffect(() => {
    if (symbolsFilters) {

      if (connectedSymbols.includes(symbol)) {
        futures24hSubscribe(symbol);  
      } else {
        futures24hUnSubscribe(symbol);
        setConnectedSymbols(prev => prev.filter(item => item !== symbol));
      }
    } else {
      if (isVisible) {
        futures24hSubscribe(symbol);

        if(!connectedSymbols.includes(symbol)) {
          setConnectedSymbols(prev => [...prev, symbol]); 
        }   
      } else {
        futures24hUnSubscribe(symbol);
        setConnectedSymbols(prev => prev.filter(item => item !== symbol));
      }
    }
  }, [symbolsFilters, symbol, isVisible]);

  useEffect(() => {

    if (isVisible) {
      setConnectedSymbols(prev => {
        if (prev.includes(symbol)) {
          return prev.filter(item => item === symbol);
        }

        return [...prev, symbol]; 
      });
    } else {
      setConnectedSymbols(prev => { 
        return prev.filter(item => item !== symbol); 
      });
    }
  }, [symbolsFilters, symbol, isVisible]);

  useEffect(() => { 

    return () => futures24hUnSubscribe(symbol);
  }, []);  
  return <>
    <Grid ref={symbolRef} container sx={{cursor: "pointer", backgroundColor: activeSymbol === symbol ? "#B41C18" : ""}} onClick={() => setActiveSymbol(symbol)} borderBottom="1px solid #EEEEEE" py={1} px={1.2}>
      <Grid item xs={6.5} display="flex">
        <StarIcon sx={{fontSize: 14, mt: .3}} />
        <Typography color={activeSymbol === symbol ? "#fff" : "000000DE"} fontSize={13} fontWeight={300} ml={.3}>{symbol}</Typography>
      </Grid>
      {
        coin ? (
          <Grid item xs={5.5} display="flex" justifyContent="space-between">
            <Typography fontSize={13} color={activeSymbol === symbol ? "#fff" : ""} fontWeight={300}>${FormatPrice({amount: coin.price, currency_iso_code: "USD", dec: "decimal"})}</Typography>
            <Typography fontSize={13} color={activeSymbol === symbol ? "#fff" : coin.percent >= 0 ? "#006943" : "#B41C18"} fontWeight={300}>
              {coin.percent >= 0 ? `+${coin.percent}` : coin.percent}%
            </Typography>
          </Grid>
        ) : (
          <Grid item xs={5} display="flex" justifyContent="space-between">
            <Skeleton variant="text" width="40px" height="12px" sx={{bgcolor: "#454545"}} />
            <Skeleton variant="text" width="20px" height="12px" sx={{bgcolor: "#006943"}} />
          </Grid>)
      }
    </Grid>
  </>;
};

