#include "Task.h"
#include <unistd.h>

void Task::start(const int ssrc) {
    std::unique_lock<std::mutex> lock(m_mutex);
    auto thread_iter = m_threads.find(ssrc);
    if (thread_iter == m_threads.end()) {
        m_threads[ssrc] = std::thread(&Task::worker, this, ssrc);
        m_threads[ssrc].detach();
        lock.unlock();
        add(ssrc);
    }
}

void Task::add(const int ssrc) {
    {
        std::unique_lock<std::mutex> lock(m_stream_mutex);
        // ... add to stream threads
    }
    {
        std::unique_lock<std::mutex> lock(m_ssrc_mutex);
        // ... add to ssrc threads
    }
}

void Task::rm(const int ssrc) {
    {
        std::unique_lock<std::mutex> lock(m_stream_mutex);
        // ... remove from stream threads
    }
    {
        std::unique_lock<std::mutex> lock(m_ssrc_mutex);
        // ... remove from ssrc threads
    }
}

void Task::stop(const int ssrc) {
    std::unique_lock<std::mutex> lock(m_mutex);
    auto thread_iter = m_threads.find(ssrc);
    if (thread_iter != m_threads.end()) {
        m_stop_condition.notify_all();
        lock.unlock();
        rm(ssrc);
    }
}

void Task::destroy(const int ssrc) {
    std::unique_lock<std::mutex> lock(m_mutex);
    auto thread_iter = m_threads.find(ssrc);
    if (thread_iter != m_threads.end()) {
        m_threads.erase(thread_iter);
    }
}

void Task::worker(const int ssrc) {
    while (true) {
        // ...
        rm(ssrc);
        sleep(5);
    }
}
