    int empty() {
        if (top == 0) {
            cout << "stack is empty." << endl;
            return 1;
        }
        return 0;
    }
    int full() {
        if (top == MAX_SIZE) {
            cout << "stack is full." << endl;
            return 1;
        }
        return 0;
    }
    ~Stack() {}
    void push(T dd);
    T pop();
};

template<class T>
void Stack<T>::push(T dd) {
    if(top==MAX_SIZE ) {
        cout<<"stack is full."<<endl;
        return;
    }
    stck[top]=dd;
    top++;
}

template<class T>
T Stack<T>::pop() {
    top--;
    if(top==-1) {
        cout<<"stack is empty."<<endl;
        return -1;
    }
    return stck[top];
}

int main() {
    Stack<int> st1; //定义模板类对象 st1,其中模板参数类型为 int 
    for(int i=0; i<MAX_SIZE; i++) {
        st1.push(i+1); //将数据 i+1 添加到栈中，即 i+1 入栈
    }
    int num;
    for(int i=0; i<MAX_SIZE; i++) {
        num=st1.pop(); //栈项元素出栈并显示
        if(num!=-1) {
            cout<<num<<" ";
        }
    }
    cout<<endl;
    return 0;
}
