function getResourcesFromCsv(csvPath) {
  let resources = [];

  // Add the CSV file itself to the resources array
  resources.push({ 'name': csvPath, 'path': csvPath });

  // Add the default image to the resources array
  resources.push({
    'name': 'default.png', 
