using System;
using System.Threading.Tasks;
using WolfLive.Api;

public class GroupChatBot
{
    private readonly string _apiKey;
    private readonly int _groupId;
    private readonly WolfLiveApi _api;

    public GroupChatBot(string apiKey, int groupId)
    {
        _apiKey = apiKey;
        _groupId = groupId;
        _api = new WolfLiveApi(_apiKey);
    }

    public async Task SendMessage(string message)
    {
