```csharp
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using WolfLive.Api;

namespace MyFirstBot
{
    public class Program
    {
        public static async Task Main(string[] args)
        {
            var accountsList = new List<Tuple<string, string>>
            {
                new Tuple<string, string>("email1", "password1"),
                new Tuple<string, string>("email2", "password2"),
                // Add more accounts here
            };

            List<Task> tasks = new List<Task>();

            foreach (var account in accountsList)
            {
                tasks.Add(LoginAndConnect(account.Item1, account.Item2));
            }

            // Wait for all account connections to complete
            await Task.WhenAll(tasks);
            await Task.Delay(-1);
        }

        private static async Task LoginAndConnect(string email, string password)
        {
            var client = new WolfClient();

            var loggedIn = await client.Login(email, password);

            if (!loggedIn)
            {
                Console.WriteLine($"Failed to login for {email}!");
                return;
            }

            Console.WriteLine($"Login successful for {email}!");
        }
    }
}
```

