            int x = buffer[1];
            int y = buffer[2];
            game.board[y][x] = current->player;

            // Store the move in the game state
            game.moves[game.move_count].x = x;
            game.moves[game.move_count].y = y;
            game.moves[game.move_count].player = current->player;
            game.move_count++;

            int winner = check_win(game.board);
            if (winner > 0 || game.move_count == 9)
            {
                game_over = 1;
                memset(buffer, 0, BUF_SIZE);
                buffer[0] = END;
                buffer[1] = winner;

                for (int i = 0; i < player_count; i++)
                {
                    if (write(players[i].sockfd, buffer, BUF_SIZE) < 0)
                    {
                        perror("Error writing to socket");
                    }
                }
            }
            else
            {
                currentPlayer = (currentPlayer + 1) % player_count;
            }
        }
        else if (buffer[0] == LFT)
        {
            game_over = 1;
            memset(buffer, 0, BUF_SIZE);
            sprintf(buffer + 1, "Player %d left the game.", current->player);
            buffer[0] = TXT;

            for (int i = 0; i < player_count; i++)
            {
                if (i != currentPlayer)
                {
                    if (write(players[i].sockfd, buffer, BUF_SIZE) < 0)
                    {
                        perror("Error writing to socket");
                    }
                }
            }
        }
        else
        {
            perror("Invalid message received");
            game_over = 1;
        }
    }

    for (int i = 0; i < player_count; i++)
    {
        close(players[i].sockfd);
    }

    return 0;
}
```

Now the server stores all the moves in the `GameState` structure. It correctly sends the game state to the clients, and they can display the entire game history if needed.

