3. Now, let's create the JavaScript Class to handle the accordion actions:

```javascript
// script.js

class Accordion {
  constructor(accordionElement) {
    this.accordionElement = accordionElement;
    this.headers = Array.from(
      accordionElement.querySelectorAll('.accordion__header')
    );
    this.init();
  }

  init() {
    this.headers.forEach((header) => {
      header.addEventListener('click', this.toggle.bind(this));
    });
  }

  toggle(event) {
    const header = event.currentTarget;
    const content = header.nextElementSibling;

    if (content.style.maxHeight) {
      content.style.maxHeight = null;
      header.classList.remove('active');
    } else {
      const expandedContent = this.accordionElement.querySelector(
        '.accordion__content[style]'
      );
      if (expandedContent) {
        expandedContent.style.maxHeight = null;
        expandedContent.previousElementSibling.classList.remove('active');
      }
      content.style.maxHeight = content.scrollHeight + 'px';
      header.classList.add('active');
    }
  }
}

document.addEventListener('DOMContentLoaded', function () {
  const accordionElement = document.querySelector('.accordion');
  const accordion = new Accordion(accordionElement);
});
```

In the `Accordion` class here's what we do:

- We create the class constructor that accepts an `accordionElement` as a parameter and initializes the class properties.
- We have the `init()` method that assigns the click event listeners to each header.
- We also have the `toggle()` method that handles the expanding and collapsing of accordion sections.

Now, you can create a new `Accordion` instance by simply passing the DOM element for any accordion on the page, making it a reusable and extendable component built using vanilla JavaScript and ES6 classes.

