private void Start()
{
InitializePlayer();

if (Group == CharacterGroup.Player)
{
_isPlayerControlled = true;
}
}

private void Update()
{
UpdateReloadTimer();
UpdateHealthBarAndText();

if (_isPlayerControlled)
{
PerformMovement();
PerformAimingAndShooting();
UpdateShotDelayTimer();
}
}

private void InitializePlayer()
{
_currentHealth = MaxHealth;
_currentBullets = MaxBullets;
}

private void UpdateReloadTimer()
{
if (_currentBullets < MaxBullets)
{
_reloadTimer += Time.deltaTime;

if (_reloadTimer >= ReloadTime)
{
_reloadTimer = 0f;
_currentBullets++;
UpdateBulletsText();
}
}
}

private void UpdateHealthBarAndText()
{
_healthBar.UpdateHealthBar(MaxHealth, _currentHealth);
_healthText.text = _currentHealth.ToString();
}

private void PerformMovement()
{
_movementInput.x = Input.GetAxisRaw(“Horizontal”);
_movementInput.y = Input.GetAxisRaw(“Vertical”);
_movementInput.Normalize();

_currentSpeed = MovementSpeed * _movementInput.magnitude;
Vector3 movement = new Vector3(_movementInput.x, _movementInput.y, 0f) * _currentSpeed * Time.deltaTime;

transform.position += movement;
}

private void PerformAimingAndShooting()
{
UpdateAimDirectionBasedOnControlMode();

if (_isAiming)
{
UpdateSightLine();
TryFireBullet();
}
else
{
DestroySightLine();
}
}

private void UpdateShotDelayTimer()
{
if (!_canShoot && _hasFiredRecently)
{
_shotTimer -= Time.deltaTime;

if (_shotTimer <= 0f)
{
_canShoot = true;
_hasFiredRecently = false;
}
}
}

private void UpdateAimDirectionBasedOnControlMode()
{
switch (CurrentControlMode)
{
case ControlMode.Mouse:
if (Input.GetMouseButtonDown(0)) StartAiming();
else if (Input.GetMouseButtonUp(0)) StopAiming();
break;
case ControlMode.Joystick:
if (Mathf.Abs(_variableJoystick.Horizontal) > 0.1f || Mathf.Abs(_variableJoystick.Vertical) > 0.1f)
{
if (!_isAiming) StartAiming();
}
else
{
if (_isAiming) StopAiming();
}
break;
case ControlMode.AI:
if (_shootingAgent != null)
{
UpdateAimDirectionFromAI();
}
break;
}
}

private void UpdateAimDirectionFromAI()
{
float horizontal = 0f;
float vertical = 0f;

if (_shootingAgent.TryGetComponent<BehaviorParameters>(out var behaviorParameters))
{
var continuousActions = behaviorParameters.BrainParameters.VectorActionSize;
var actions = _shootingAgent.GetAction();

if (actions.ContinuousActions.Length > 0) horizontal = actions.ContinuousActions[0];
if (actions.ContinuousActions.Length > 1) vertical = actions.ContinuousActions[1];
}

if (Mathf.Abs(horizontal) > 0.1f || Mathf.Abs(vertical) > 0.1f)
{
if (!_isAiming) StartAiming();
}
else
{
if (_isAiming) StopAiming();
}
}

private void StartAiming()
{
if (_sightLine != null) Destroy(_sightLine);

CreateSightLine();
SetInitialSightLinePositions();

_currentDistance = AimingDistance;
_isAiming = true;
}

private void StopAiming()
{
DestroySightLine();
TryFireBullet();

_isAiming = false;
}

private void CreateSightLine()
{
_sightLine = new GameObject(“SightLine”);

LineRenderer lineRenderer = _sightLine.AddComponent<LineRenderer>();
lineRenderer.positionCount = 2;
lineRenderer.startWidth = BulletWidth;
lineRenderer.endWidth = BulletWidth;
lineRenderer.material = CreateLineMaterial();
lineRenderer.sortingLayerName = “Background”;
lineRenderer.sortingOrder = -1;
}

private Material CreateLineMaterial()
{
Material lineMaterial = new Material(Shader.Find(“Sprites/Default”));
lineMaterial.color = Color.white;

return lineMaterial;
}

private void SetInitialSightLinePositions()
{
LineRenderer lineRenderer = _sightLine.GetComponent<LineRenderer>();
lineRenderer.SetPosition(0, transform.position);
lineRenderer.SetPosition(1, transform.position);
}

private void UpdateSightLine()
{
_lineEndPosition = (Vector2)transform.position + _aimDirection * _currentDistance;
GetComponent<LineRenderer>().SetPosition(0, transform.position);
GetComponent<LineRenderer>().SetPosition(1, _lineEndPosition);
}

private void DestroySightLine()
{
if (_sightLine == null) return;

Destroy(_sightLine);
_sightLine = null;
}

private void TryFireBullet()
{
if (!_canShoot || _currentBullets <= 0) return;

if (_shotTimer <= 0f)
{
FireBullet();

_currentBullets–;
UpdateBulletsText();

_canShoot = false;
_shotTimer = ShotDelay;
}
}

private void FireBullet()
{
GameObject bullet = Instantiate(BulletPrefab, transform.position, Quaternion.identity);

BulletController bulletController = bullet.GetComponent<BulletController>();
bulletController.SetDirection(_aimDirection);
bulletController.SetSpeed(BulletSpeed);
bulletController.SetMaxDistance(_currentDistance);
bulletController.SetGroup(Group);
bulletController.SetDamage(Damage);
bulletController.SetDamagePiercing(DamagePiercing);
}

