private void ProcessCollisions(Collider2D collision)
{
if (collision.CompareTag(“Bullet”))
{
BulletController bulletController = collision.GetComponent<BulletController>();

if (Group == CharacterGroup.Player && bulletController.Group == CharacterGroup.Ally ||
Group == CharacterGroup.Ally && bulletController.Group == CharacterGroup.Player)
{
// Ignore bullets from allies damaging the player or the player damaging allies
return;
}
else if (Group == CharacterGroup.Enemy && bulletController.Group == CharacterGroup.Player)
{
// Damage the enemy when hit by a player’s bullet
TakeDamage(bulletController.GetDamage(), bulletController.GetDamagePiercing());

if (!bulletController.GetDamagePiercing())
{
Destroy(collision.gameObject);
}

return;
}
}
}

