You can create a multi-layer sidebar navigation using vanilla JavaScript and ES6 class like this:

1. Create a basic HTML structure for the sidebar navigation:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Multi-layer Sidebar Navigation</title>
  <style>
    .sidebar {
      width: 250px;
      height: 100%;
      background-color: #f5f5f5;
      overflow: auto;
    }
    .nav-item > ul {
      display: none;
    }
  </style>
</head>
<body>
  <div class="sidebar" id="sidebar"></div>
  <script src="script.js"></script>
</body>
</html>
```

2. Create an ES6 class to manage the sidebar navigation and load the data dynamically:

```javascript
// script.js
class Sidebar {
  constructor(data, containerId) {
    this.data = data;
    this.container = document.getElementById(containerId);
    this.buildNavigation(this.data, this.container);
  }

  buildNavigation(data, parentElement) {
    const ul = document.createElement('ul');

    data.forEach(item => {
      const li = document.createElement('li');
      li.classList.add('nav-item');

      const a = document.createElement('a');
      a.href = item.url || '#';
      a.textContent = item.title;

      li.addEventListener('click', event => {
        event.stopPropagation();

        if (item.children && item.children.length) {
          li.classList.toggle('active');
          const subNav = li.querySelector('ul');

          if (subNav) {
            subNav.style.display = li.classList.contains('active') ? 'block' : 'none';
          }
        } else if (typeof this.onNavigationItemClick === 'function') {
          this.onNavigationItemClick(event, item);
        }
      });

      li.appendChild(a);

      if (item.children && item.children.length) {
        this.buildNavigation(item.children, li);
      }

      ul.appendChild(li);
    });

    parentElement.appendChild(ul);
  }
}
```

