#include <iostream>
#include <thread>
#include <deque>
#include <functional>
#include <future>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <memory>
#include <chrono>

class ZYLThreadPool {
public:
    ZYLThreadPool(size_t minThreads = 20, size_t maxThreads = 200)
        : _minThreads(minThreads)
        , _maxThreads(maxThreads)
        , _stop(false) {
        worker_threads.reserve(_maxThreads);
        for (size_t i = 0; i < _minThreads; ++i) {
            create_thread();
        }
    }

    void create_thread() {
        worker_threads.emplace_back([this] {
            for (;;) {
                std::function<void()> task;
                {
                    std::unique_lock<std::mutex> lock(this->_mutex);
                    this->_condVar.wait(lock, [this] {
                        return this->_stop || !this->_taskQueue.empty();
                    });
                    if (this->_stop && this->_taskQueue.empty())
                        return;
                    task = std::move(this->_taskQueue.front());
                    this->_taskQueue.pop_front();
                }
                task();
            }
        });
    }

    template <typename F, typename... Args>
    auto submit(F&& f, Args&&... args)-> std::future<typename std::result_of<F(Args...)>::type> {
        using return_type = typename std::result_of<F(Args...)>::type;

        auto task = std::make_shared<std::packaged_task<return_type()>>(std::bind(std::forward<F>(f), std::forward<Args>(args)...));

        std::future<return_type> result = task->get_future();
        {
            std::unique_lock<std::mutex> lock(_mutex);
            if (_stop) {
                throw std::runtime_error("Submit on stopped ZYLThreadPool");
            }
            if (_taskQueue.size() >= worker_threads.size() && worker_threads.size() < _maxThreads) {
                create_thread();
            }
            _taskQueue.emplace_back([task] { (*task)(); });
        }
        _condVar.notify_one();
        return result;
    }

    void cancel() {
        std::unique_lock<std::mutex> lock(_mutex);
        if (!_stop) {
            _stop = true;
            _condVar.notify_all();
        }
        for (std::thread& worker : worker_threads)
            worker.join();
    }

    size_t getNumTasks() {
        std::unique_lock<std::mutex> lock(_mutex);
        return _taskQueue.size();
    }

    ~ZYLThreadPool() {
        cancel();
    }

private:
    std::vector<std::thread> worker_threads;
    std::deque<std::function<void()>> _taskQueue;
    size_t _minThreads;
    size_t _maxThreads;
    std::mutex _mutex;
    std::condition_variable _condVar;
    bool _stop;
};

class Test {
public:
    Test(double devid)
        : _devid(devid)
        , _running(true) {
    }

    void start(ZYLThreadPool& threadPool) {
        _future = threadPool.submit(&Test::_task, this);
    }

    void stop() {
        {
            _running = false;
            std::unique_lock<std::mutex> lock(_mutex);

            if (_future.valid()) {
                _future.get();
                lock.unlock();
                _cleanupResources();
            }
        }
    }

private:
    std::mutex _mutex;
    double _devid;
    std::deque<double> _dequeue_packets;
    std::future<void> _future;
    bool _running;

    void _cleanupResources() {
        std::unique_lock<std::mutex> lock(_mutex);
        _dequeue_packets.clear();
    }

    void _task() {
        std::unique_lock<std::mutex> lock(_mutex);
        while (_running) {
            if (_dequeue_packets.empty()) {
                //std::cout << "running task"<< std::endl;
                continue;
            }
            double packet = _dequeue_packets.front();
            _dequeue_packets.pop_front();
            lock.unlock();
            std::cout << "running task" << std::endl;
            lock.lock();
        }
		std::cout<<"task end"<<std::endl;
    }
};

int main() {
    ZYLThreadPool zylThreadPool(20, 200);
    std::vector<std::shared_ptr<Test>> tests;
	std::cout<<"start all task"<<std::endl;
    for (int i = 0; i < 100; ++i) {
        auto test = std::make_shared<Test>(1.0);
        test->start(zylThreadPool);
        tests.push_back(test);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));
	std::cout<<"stop all task"<<std::endl;
    for (auto& test : tests) {
        test->stop();
    }
    tests.clear();

	while(1){
		std::this_thread::sleep_for(std::chrono::seconds(3));
	}

    return 0;
}
问题：上面例子出现了死锁
1.开启100个任务，能无阻塞启动，此时的线程数是97
2.停止100个任务，出现死锁，此时的线程数还是97，在停止第一个任务的时候就阻塞住了
3.加日志打印，经过linux服务器测试加日志打印，是在stop函数调用_future.get();这里阻塞住了
请修复

首先分析一下你的代码，你在 `_task` 方法中使用了 `while (_running)` 循环，在循环中不断检查 `_dequeue_packets` 是否为空，然后执行任务。在 `stop` 方法中，你设置 `_running` 为 `false` 然后调用 `_future.get()` 等待 `_task` 方法执行完毕。

这里可能出现死锁的原因是 `_task` 方法可能在 `_running` 变为 `false` 之后，还在执行 `while` 循环中的其他部分。比如，当 `_dequeue_packets` 为空时，`_task` 方法执行到 `continue`，而在此时在另一个线程中调用 `stop` 方法，`_running` 被设置为 `false`，但是 `_task` 方法仍然在循环中。此时，`stop` 方法调用 `_future.get()`，等待 `_task` 方法完成，但是 `_task` 方法却一直在循环中，导致死锁。

有一种简单的方法来解决这个问题，就是在 `_task` 方法中的 `continue` 之前加一个检查 `_running` 的语句，确保循环会在 `_running` 变为 `false` 时退出。

修改后的 `_task` 方法如下：

```cpp
void _task() {
    std::unique_lock<std::mutex> lock(_mutex);
    while (_running) {
        if (_dequeue_packets.empty()) {
            //(std::cout << "running task"<< std::endl;
            lock.unlock();
            lock.lock();
            continue;
        }
        double packet = _dequeue_packets.front();
        _dequeue_packets.pop_front();
        lock.unlock();
        std::cout << "running task" << std::endl;
        lock.lock();
    }
    std::cout<<"task end"<<std::endl;
}
```

这样，当 `_running` 变为 `false` 时，`_task` 方法就能够跳出循环，避免死锁。但需要注意的是，这样的设计可能会导致 `_task` 方法不断地在循环中检查 `_dequeue_packets`，消耗过多 CPU 资源。你可能需要考虑使用条件变量或其他同步机制来避免这种情况。

To create a Node.js app that can trade using Uniswap V3 SDK, follow the steps below:

1. Install necessary tools

