public class ShootingAgent : Agent
{
    public PlayerController playerController;
    public float visibleAreaWidth = 26;
    public float visibleAreaHeight = 17;

    [Header("Observation Configurations")]
    public int numberOfPlayerTypes = 3; // Set this to the number of player types you have
    public int numberOfPowerUpTypes = 2; // Set this to the number of power-up types you have
    public LayerMask playersAndPowerupsLayer;
    public LayerMask wallsLayer;

