    {
        // Reset the player and environment for a new episode
        // …
        playerController.InitializePlayer();
    }

    public override void CollectObservations(VectorSensor sensor)
    {
        // Collect player and power-up observations within visible range
        Vector3 minRange = transform.position - new Vector3(visibleAreaWidth / 2, visibleAreaHeight / 2, 0);
        Vector3 maxRange = transform.position + new Vector3(visibleAreaWidth / 2, visibleAreaHeight / 2, 0);
        Collider2D[] colliders = Physics2D.OverlapAreaAll(minRange, maxRange, playersAndPowerupsLayer);
        foreach (Collider2D collider in colliders)
        {
            Vector3 relativePos = collider.transform.position - transform.position;
            sensor.AddObservation(relativePos.x);
            sensor.AddObservation(relativePos.y);

            // Add additional information for each object (e.g., type, team ID, etc.)
            CollectObjectInfo(sensor, collider.gameObject);
        }

        // Collect wall observations within visible range
        colliders = Physics2D.OverlapAreaAll(minRange, maxRange, wallsLayer);
        foreach (Collider2D collider in colliders)
        {
