const IUniswapV3PoolABI = require('@uniswap/v3-core/artifacts/contracts/interfaces/IUniswapV3Pool.sol/IUniswapV3Pool.json');
const QuoterABI = require('@uniswap/v3-periphery/artifacts/contracts/lens/Quoter.sol/Quoter.json');

const V3_SWAP_ROUTER_ADDRESS = '0xE592427A0AEce92De3Edee1F18E0157C05861564';
const WALLET_ADDRESS = '0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266';
const WALLET_SECRET = '0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80';
const INFURA_TEST_URL = 'https://mainnet.infura.io/v3/2d5bc62bb8d748cebfc64763e719cb4f';
const QUOTER_CONTRACT_ADDRESS = '0xb27308f9F90D607463bb33eA1BeBb41C27CE5AB6';

const provider = new ethers.providers.JsonRpcProvider(INFURA_TEST_URL);

const chainId = 1;
const router = new AlphaRouter({ chainId: chainId, provider: provider });

const token0 = new Token(chainId, '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2', 18, 'WETH', 'Wrapped Ether');
const token1 = new Token(chainId, '0x1f9840a85d5af5bf1d1762f925bdaddc4201f984', 18, 'UNI', 'Uniswap Token');

async function main() {
  const poolWithFee = await router.bestPoolsSingleHop(token0, token1, "3000");
  const pool = poolWithFee[0].pool;

  const inputAmount = CurrencyAmount.fromRawAmount(token0, ethers.utils.parseUnits('0.001', 18));

  const quotedAmountOut = await router.quoteExactInput(inputAmount, [pool]);

  const options = {
    slippageTolerance: new Percent(50, 10_000), // 50 bips, or 0.50%
    deadline: Math.floor(Date.now() / 1000) + 60 * 20, // 20 minutes from the current Unix time
    recipient: WALLET_ADDRESS,
  };

  const swapRoute = await router.routeExactInput(inputAmount, quotedAmountOut.outputAmount, { ...options });

  // Sign and send the transaction
  const wallet = new ethers.Wallet(WALLET_SECRET, provider);
  const nonce = await wallet.getTransactionCount();

  const GAS_ESTIMATE_TRANSACTION = { to: swapRoute.ultimatelyFeaturable.route.route[0].pool.liquidityProvider, data: swapRoute.toHexString() };
  const gasLimit = await wallet.estimateGas(GAS_ESTIMATE_TRANSACTION);
  const gasPrice = await provider.getGasPrice();

  const transaction = {
    to: V3_SWAP_ROUTER_ADDRESS,
    data: swapRoute.toHexString(),
    gasLimit,
    gasPrice,
    nonce,
  };

  const signedTransaction = await wallet.signTransaction(transaction);
  const txResult = await provider.sendTransaction(signedTransaction);

  console.log(`Transaction sent! Waiting for confirmation...`);
  console.log(`Hash: ${txResult.hash}`);

  const receipt = await txResult.wait();

  console.log(`Transaction confirmed in block ${receipt.blockNumber}`);
}

main().catch(e => {
  console.error(`Error executing the swap: ${e.message}`);
  process.exit(1);
});
```

