    let mut child = Command::new("gcc")
        .arg("-Wall")
        .arg("-o")
        .arg("my_program")
        .arg("my_program.c")
        .stdout(Stdio::piped())
        .spawn()
        .expect("failed to execute child");

    let stdout = child
