fun sortRows(rows: List<TableRow>, sortBy: String, ascending: Boolean): List<TableRow> {
    return when (sortBy) {
        "name" -> {
            val comparator = compareBy<TableRow> { (it.getChildAt(1) as TextView).text.toString() }
            if (ascending) rows.sortedWith(comparator) else rows.sortedWith(comparator.reversed())
        }
        "year" -> {
            val comparator = compareBy<TableRow> { (it.getChildAt(2) as TextView).text.toString().toInt() }
            if (ascending) rows.sortedWith(comparator) else rows.sortedWith(comparator.reversed())
        }
        else -> rows
    }
}
```

