Pseudocode:

1. Initialize the pins and variables
2. Configure the pins as OUTPUT
3. Initialize the timer
4. Start the timer
5. Read the "Start/stop" button
6. If the button is pressed, start flashing the LEDs
7. Flashing sequence:
   a. Turn on LEDs connected to 0, 1, 2, and 3 pins
   b. Turn off LEDs connected to 4, 5, 6, and 7 pins
   c. Wait for the timer to reach the desired duration
   d. Reset the timer
   e. Turn off LEDs connected to 0, 1, 2, and 3 pins
   f. Turn on LEDs connected to 4, 5, 6, and 7 pins
   g. Wait for the timer to reach the desired duration
   h. Reset the timer
8. Repeat steps 5 to 7

Arduino code:

```cpp
#include <Ticker.h>

const int ledPins[] = {0, 1, 2, 3, 4, 5, 6, 7};
const int buttonPin = 8;
const int flashingInterval = 500; // in milliseconds

bool flashing = false;
bool state = false;

Ticker timer;

void setup() {
  for (int i = 0; i < 8; i++) {
    pinMode(ledPins[i], OUTPUT);
  }
  pinMode(buttonPin, INPUT_PULLUP);

  timer.attach_ms(flashingInterval, toggleLEDs);
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    flashing = !flashing;
    delay(300); // To avoid button debounce
  }
}

void toggleLEDs() {
  if (!flashing) {
    return;
  }

  state = !state;

  for (int i = 0; i < 4; i++) {
    digitalWrite(ledPins[i], state);
  }

  for (int i = 4; i < 8; i++) {
    digitalWrite(ledPins[i], !state);
  }
}
```

