        val balance = CompletableDeferred<Double>()

        fun setResult(value: Double) {
            balance.complete(value)
        }
    }

    class AccountVerifier : VerifierState() {
        private val accounts = mutableMapOf<CompletableDeferred<Double>, Double>()

        @OnEnter
        fun onEnter() {
            accounts.clear()
        }

        @OnExit
        fun onExit(get: Double?) {
            for ((accountState, expectedBalance) in accounts) {
                check(accountState.await() == expectedBalance)
            }
        }

        fun addAccount(accountState: AccountState, initialBalance: Double) {
            accounts[accountState.balance] = initialBalance
        }
    }

    class Actor(model: StateModel<AccountState>, verifier: Verifier<AccountVerifier, Double>) : CheckedActor<AccountState, CompletableDeferred<Double>>(model, verifier) {
        override fun AccountState.extractState() = this
        override fun createModelChecker() = ModelCheckerBuilder(AccountVerifier(), ::AccountState)
            .initialState { AccountState() }
            .addTransition { state ->
                val balance = state.balance.getCompleted()
                val (message, accountState) = newState(balance, state)
                when (message) {
                    is IncOperation -> accountSafe.modify(message.difference)
                    is GetOperation -> {
                        accounts.addAccount(accountState, balance)
                        message.response.complete(balance)
                    }
                }
                accountState
            }
            .build()

        private fun newState(balance: Double, state: AccountState): Pair<AccountMsg, AccountState> {
            return if (numOfThreads > 1 && rnd.nextBoolean()) {
                IncOperation(rnd.nextDouble(-100.0, 100.0)) to state
            } else {
                GetOperation(state.balance) to AccountState().apply {
                    setResult(balance)
                }
            }
        }
    }

    private val numOfThreads = 2
    private val actorsPerThread = 2
    private val verifier = AccountVerifier()
    private val model = StateModel<AccountState>().apply {
        repeat(numOfThreads * actorsPerThread) {
            addCustomCreateOperation(::AccountState)
        }
        addCustomResetOperation(AccountState::class) { completeAll() }
    }

    @Test
    fun runTest() {
        LinChecker.check(Actor(model, verifier), numThreads = numOfThreads, actorsPerThread = actorsPerThread, loggingLevel = LoggingLevel.INFO)
    }
}
```

