            pstmt.setString(1, city);
            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getDouble("avg_temp");
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return 0.0; // или другое значение по умолчанию, если не удалось получить среднее значение
    }


