package com.dootz.spellcastsolvergui.model.board;

import com.dootz.spellcastsolvergui.model.word.Letter;

public class BoardParser {
    private String[][] tileStrings;

    public BoardParser(String[][] tileStrings) {
        this.tileStrings = tileStrings;
    }

    public Tile[][] parse() {
        int numRows = tileStrings.length;
        int numCols = tileStrings[0].length;
        Tile[][] parsedBoard = new Tile[numRows][numCols];

        for (int row = 0; row < numRows; row++) {
            for (int col = 0; col < numCols; col++) {
                String tile = tileStrings[row][col];
                char lastCharacter = Character.toLowerCase(tile.charAt(tile.length() - 1));
                Letter.Position position = new Letter.Position(row, col);
                boolean hasGem = false;
                int letterMultiplier = 1, wordMultiplier = 1;

                if (tile.contains("*")) {
                    hasGem = true;
                } else if (tile.contains("&")) {
                    wordMultiplier = 2;
                } else if (tile.contains("2")) {
                    letterMultiplier = 2;
                } else if (tile.contains("3")) {
                    letterMultiplier = 3;
                }
                parsedBoard[row][col] = new Tile(new Letter(lastCharacter, position, hasGem, letterMultiplier,
                        wordMultiplier));
            }
        }
        return parsedBoard;
    }

    public void setTileStrings(String[][] tileStrings) {
        this.tileStrings = tileStrings;
    }

    public String[][] getTileStrings() {
        return tileStrings;
    }
}
