```typescript
import { useState, useEffect, useRef } from "react";

type CupItem = {
  futures_price_micro: number;
  quantity: number;
  spot_quantity: number;
  side: string;
};

const TradingCup = () => {
  const { cup } = useRustWsServer();
  const [tradesArr, setTradesArr] = useState<Array<CupItem>>([]);
  const canvasWidth = 100; // Define your canvas width
  const canvasHeight = 100; // Define your canvas height
  const rowHeight = 10; // Define row height
  const bubbleSize = 10; // Define bubble size constant
  const orderFeedCanvas = useRef<HTMLCanvasElement | null>(null);

  const deepGreen = (ratio: number): string => {
    const r = Math.floor(0 + (255 - 0) * ratio);
    const g = Math.floor(128 + (255 - 128) * ratio);
    const b = Math.floor(0 + (255 - 0) * ratio);
    return `rgb(${r}, ${g}, ${b})`;
  };

  const deepRed = (ratio: number): string => {
    const r = Math.floor(255 + (255 - 255) * ratio);
    const g = Math.floor(0 + (255 - 0) * ratio);
    const b = Math.floor(0 + (255 - 0) * ratio);
    return `rgb(${r}, ${g}, ${b})`;
  };

  const clamp = (value: number, min: number, max: number): number => {
    return Math.min(Math.max(value, min), max);
  };

  const renderTrade = (prev: CupItem, item: CupItem, index: number) => {
    if (orderFeedCanvas.current) {
      const ctx = orderFeedCanvas.current.getContext("2d");
      let xPos = canvasWidth - (index * (bubbleSize * 1.5)) - bubbleSize;
      const y = item.side === "Buy" ? 50 : 150; // Adjust this value based on your calculations

      const label = item.quantity.toFixed(2); // Show 2 decimal places for quantity
      const { width: textWidth } = ctx.measureText(label);
      const size = clamp(item.quantity / 400 * 35, (textWidth / 2) + 3, 35); // Replace 400 with the maximum quantity in your data

      const bubbleX = xPos;
      const bubbleY = y + 8;
      ctx.beginPath();
      const bigRatio = (size / 35) / 3;
      ctx.fillStyle = item.side === "Buy"
        ? deepGreen(bigRatio)
        : deepRed(bigRatio);
      ctx.strokeStyle = "black";
      ctx.arc(xPos, bubbleY, size, 0, 2 * Math.PI);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = "#FFFFFF";
      ctx.fillText(label, bubbleX - (textWidth / 2), (bubbleY + (rowHeight / 2)) - 2);
    }
  };

  const renderTrades = () => {
    if (orderFeedCanvas.current) {
      const ctx = orderFeedCanvas.current.getContext("2d");
      ctx.clearRect(0, 0, canvasWidth, canvasHeight);
      tradesArr.reduce((prev: CupItem, cur: CupItem, index: number) => {
        renderTrade(prev, cur, tradesArr.length - index);
        prev = cur;
        return prev;
      }, {} as CupItem);
    }
  };

  useEffect(() => {
    setTradesArr(cup);
  }, [cup]);

  useEffect(() => {
    renderTrades();
  }, [tradesArr]);

  return (
    <div>
      <canvas
        ref={orderFeedCanvas}
        width={canvasWidth}
        height={canvasHeight}
        style={{ border: "1px solid black" }}
      />
    </div>
  );
};

export default TradingCup;
```

