        {
            get => Get(key);
            set => Store(key, value, expiresAfter);
        }

        public void StartRemovingExpiredItems()
        {
            Task.Factory.StartNew(RemoveExpiredItemsInBackground,
                _cancellationTokenSource.Token,
                TaskCreationOptions.LongRunning,
                TaskScheduler.Default);
        }

        public void Dispose()
        {
            _cancellationTokenSource.Cancel();
        }

        private void RemoveExpiredItemsInBackground()
        {
            while (!_cancellationTokenSource.IsCancellationRequested)
            {
                var expiredKeys = _cache
                    .Where(i => i.Value.IsExpired)
                    .Select(i => i.Key)
                    .ToArray();

                foreach (var key in expiredKeys)
                {
                    _cache.TryRemove(key, out var item);
                }

                Thread.Sleep(ExpiryCheckIntervalMs); 
            }
        }

        private class CacheItem<T>
        {
            public T? Value { get; }
            public bool IsExpired => DateTimeOffset.UtcNow - Created >= ExpiresAfter;

            private DateTimeOffset Created { get; }
            private TimeSpan ExpiresAfter { get; }

            public CacheItem(T? value, DateTimeOffset created, TimeSpan expiresAfter)
