```cpp
#pragma once
#include <unordered_map>
#include <vector>
#include <cstdint>
#include <typeindex>
#include <functional>
#include <array>

class Event
{
public:
    virtual ~Event() {}
};

class EventBus
{
public:
    template <typename EventType>
    void Subscribe(std::function<void(const EventType &)> callback)
    {
        auto wrapper = [callback](const Event *eventPtr)
                       {
                           callback(static_cast<const EventType &>(*eventPtr));
                       };
        callbacks_[typeid(EventType)].push_back(wrapper);
    }

    template <typename EventType>
    void Unsubscribe()
    {
        callbacks_.erase(typeid(EventType));
    }

    template <typename EventType>
    void Dispatch(const EventType &event)
    {
        auto it = callbacks_.find(typeid(EventType));
        if (it != callbacks_.end())
        {
            for (auto &callback : it->second)
            {
                callback(&event);
            }
        }
    }

private:
    std::unordered_map<std::type_index, std::vector<std::function<void(const Event *)>>> callbacks_;
};

class ECS
{
    // ... (rest of ECS implementation, unchanged)

public:
    EventBus &GetEventBus()
    {
        return eventBus_;
    }

private:
    EventBus eventBus_;
};

