Then, create the Vue3 component and add the code to perform the SVG morph.

```javascript
Vue.createApp({
    data() {
        return {
            currentSVG: 1,
            svg1: `M344.5 244.5L308 291L231 279L74.5 296.5H11V241L0 98.5L41.5 0L158.5 18.5L280.5 0L359.27 13.5279 L368.5 79L344.5 244.5Z`,
            svg2: `M16 197.5L0 53L52 0.5L176 30.6295 L276.5 0.5L363.5 45.5L321.5 190L334 296.5L165 284.009 L66.5 303H24.5 L0 284.009L16 197.5Z`,
        };
    },
    template: `
    <svg @mouseover="morph" @mouseout="morph" width="369" height="297" viewBox="0 0 369 297" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path :d="mainPath" ref="mainPath" fill="#D9D9D9" />
    </svg>`,

    methods: {
        morph() {
            const currentPath = this.currentSVG === 1 ? this.svg1 : this.svg2;
            const newPath = this.currentSVG === 1 ? this.svg2 : this.svg1;

            KUTE.to(
                this.$refs.mainPath, {
                    path: newPath,
                }, {
                    duration: 500,
                    easing: "easingCubicInOut",
                }
            ).start();

            this.currentSVG = this.currentSVG === 1 ? 2 : 1;
        },
    }
