```csharp
public RayPerceptionSensorComponent2D rayPerception;

public override void CollectObservations(VectorSensor sensor)
{
    // Retrieve the sensor's observations in the form of RayPerceptionOutputs
    RayPerceptionOutput output = rayPerception.GetRayPerceptionOutput();

    // Add the HitFraction and subobservation list to the observation list
    foreach (RayPerceptionOutput.RayOutput rayOutput in output.RayOutputs)
    {
        sensor.AddObservation(rayOutput.HitFraction);

        // Customize this for loop to match the DetectableTags set on the sensor.
        for (int i = 0; i < 2; i++)
        {
            sensor.AddObservation(rayOutput.PassedTags.Contains(rayPerception.RayDetector.DetectableTags[i]));
        }
    }

    // Add player's position as observation
    sensor.AddObservation(transform.localPosition);
}
```

