public override void CollectObservations(VectorSensor sensor)
{
    // Add player position
    sensor.AddObservation(transform.localPosition);

    // Add distance to nearest wall
    RaycastHit2D hit = Physics2D.CircleCast(transform.position, 0.5f, Vector2.zero, 0f, LayerMask.GetMask("Wall"));
    float distanceToNearestWall = hit.distance;
    sensor.AddObservation(distanceToNearestWall);

    // Add food positions relative to the player position
    List<GameObject> allFood = trainingArea.GetFoodInstances();
    foreach (GameObject food in allFood)
    {
