    x: 0.5,
    y: 0.5,
    z: -1,
  },
  {
    x: -0.3,
    y: -0.5,
    z: -1,
  },
  {
    x: -0.3,
    y: 0.8,
    z: -1,
  },
];

let angleX = 0;
let angleY = 0;
let angleZ = 0;

let scale = 0.025;
let zoom = 1;
let offsetX = 0.5;
let offsetY = 0.5;

let indexToDrag = -1;

function hover(event) {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  let closestDistance = Infinity;
  let closestIndex = -1;

  vertices.forEach((vertex, index) => {
    let [screenX, screenY] = project(vertex.x, vertex.y, vertex.z);

    let distance = Math.sqrt((x - screenX) ** 2 + (y - screenY) ** 2);
    if (distance < closestDistance) {
      closestDistance = distance;
      closestIndex = index;
    }
  });

  if (closestDistance < 10) {
    indexToDrag = closestIndex;
  } else {
    indexToDrag = -1;
  }
}

function drag(event) {
  if (indexToDrag !== -1 && event.which === 1) {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    vertices[indexToDrag].x = x / canvas.width;
    vertices[indexToDrag].y = y / canvas.height;
  }
}

canvas.addEventListener("mousedown", hover);
canvas.addEventListener("mousemove", drag);
canvas.addEventListener("mouseup", () => {
  indexToDrag = -1;
});

function project(x, y, z) {
  const posX = (x - offsetX) * scale;
  const posY = (y - offsetY) * scale;
  const posZ = z * scale;

  return [
    (posX * (zoom + posZ) + canvas.width / 2),
    (posY * (zoom + posZ) + canvas.height / 2),
  ];
}

function render() {
  // Clear screen
  ctx.fillStyle = "#FFF";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const rotX = rotateX(angleX);
  const rotY = rotateY(angleY);
  const rotZ = rotateZ(angleZ);

  let rotatedVertices = vertices.map((vertex) => {
    const cx = vertex.x - offsetX;
    const cy = vertex.y - offsetY;
    const cz = vertex.z - offsetY;

    const rotated = transform(transform(transform([cx, cy, cz], rotX), rotY), rotZ);

    return {
      x: rotated[0] + offsetX,
      y: rotated[1] + offsetY,
      z: rotated[2] + offsetY
    };
  });

  ctx.fillStyle = "red";
  ctx.beginPath();
  rotatedVertices.forEach((vertex) => {
    drawCircle(ctx, ...project(vertex.x, vertex.y, vertex.z), 5);
  });
  ctx.fill();

  requestAnimationFrame(render);
}

function rotateX(angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return [
    [1, 0, 0],
    [0, c, -s],
    [0, s, c],
  ];
}

function rotateY(angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return [
    [c, 0, s],
    [0, 1, 0],
    [-s, 0, c],
  ];
}

function rotateZ(angle) {
  const c = Math.cos(angle);
  const s = Math.sin(angle);
  return [
    [c, -s, 0],
    [s, c, 0],
    [0, 0, 1],
  ];
}

function transform(point, matrix) {
  const [x, y, z] = point;
  const [rowX, rowY, rowZ] = matrix;
  return [
    x * rowX[0] + y * rowX[1] + z * rowX[2],
    x * rowY[0] + y * rowY[1] + z * rowY[2],
    x * rowZ[0] + y * rowZ[1] + z * rowZ[2],
  ];
}

function drawCircle(ctx, x, y, r) {
  ctx.moveTo(x + r, y);
  ctx.arc(x, y, r, 0, 2 * Math.PI);
}

render();
window.addEventListener("resize", () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
});
```

