if (indexToDrag !== -1 && event.which === 1) {
const rect = canvas.getBoundingClientRect();
const x = event.clientX - rect.left;
const y = event.clientY - rect.top;

vertices[indexToDrag].x = x / canvas.width;
vertices[indexToDrag].y = y / canvas.height;
