  name: 'John Doe',
  email: 'john@example.com',
  phone: '1234567890',
  password: 'password123',
};

usersRef
  .add(user)
  .then((docRef) => {
    console.log('User added with ID:', docRef.id);
  })
  .catch((error) => {
    console.error('Error adding user:', error);
  });
```

This code adds a new user to the "Users" collection with the specified fields.

4. Retrieve users: To retrieve users from the "Users" collection, call the `get()` method on the collection reference. Call the `.then()` method on the returned promise to handle the results.

```javascript
usersRef
  .get()
  .then((querySnapshot) => {
    const users = [];
    querySnapshot.forEach((doc) => {
      const user = doc.data();
      user.id = doc.id;
