Here's the updated code that defines canvasOffsets as the result of canvas.getBoundingClientRect():

```javascript
function nearestGridIntersection(x, y) {
  const canvasOffsets = canvas.getBoundingClientRect();
  const xt = (x - canvasOffsets.left - offsetX) / zoom;
  const yt = (y - canvasOffsets.top - offsetY - canvas.height * scale * 0.3) / zoom;

  const snapX = roundToGrid(xt) * zoom + canvasOffsets.left + offsetX;
  const snapY = roundToGrid(yt) * zoom + canvasOffsets.top + offsetY + canvas.height * scale * 0.3;

  return {
    x: snapX,
    y: snapY
  };
}

