#include <iostream>
#include <vector>

using namespace std;

class Gun {
protected:
    string name;
    int mag_size, ammo;
    float damage, fire_rate, reload_time, wear;
    float skin_bonus = 0;

public:
    Gun(int ammo, float wear) : ammo(ammo), wear(wear) {}

    virtual string get_name() const {
        return name;
    }

    virtual float total_damage(int shoot_time) const {
        int mag_num = shoot_time / (mag_size / fire_rate + reload_time);
        int bullets_fired = min(ammo, mag_num * mag_size);
        float total_damage = bullets_fired * damage * wear;
        return total_damage;
    }
};

class Pistol : public Gun {
public:
    Pistol(int type, int ammo, float wear) : Gun(ammo, wear) {
        if (type == 1) {
            name = "G18";
            mag_size = 12;
            damage = 2;
            fire_rate = 1;
            reload_time = 2;
        } else {
            name = "M500";
            mag_size = 5;
            damage = 4;
            fire_rate = 0.5;
            reload_time = 2;
        }
    }
};

class Rifle : public Gun {
public:
    Rifle(int type, int ammo, float wear, float skin_bonus) : Gun(ammo, wear), skin_bonus(skin_bonus) {
        if (type == 3) {
            name = "MP40";
            mag_size = 20;
            damage = 3 + skin_bonus;
            fire_rate = 5;
            reload_time = 2;
        } else {
            name = "AK";
            mag_size = 30;
            damage = 5 + skin_bonus;
            fire_rate = 1;
            reload_time = 2;
        }
    }
};

class Sniper : public Gun {
public:
    Sniper(int type, int ammo, float wear) : Gun(ammo, wear) {
        if (type == 5) {
            name = "SVD";
            mag_size = 10;
            damage = 5;
            fire_rate = 0.5;
            reload_time = 3; // 1s extra reload time for snipers
        } else {
            name = "AWM";
            mag_size = 5;
            damage = 10;
            fire_rate = 0.5;
            reload_time = 3; // 1s extra reload time for snipers
        }
    }
};

int main() {
    int n, type, ammo = 0;
    float wear;
    float skin_bonus;

    cin >> n;
    vector<Gun*> guns;

    for (int i = 0; i < n; i++) {
        Gun *gun;
        cin >> type;

        if (type == 1 || type == 2) {
            cin >> ammo >> wear;
            gun = new Pistol(type, ammo, wear);
        } else if (type == 3 || type == 4) {
            cin >> ammo >> wear >> skin_bonus;
            gun = new Rifle(type, ammo, wear, skin_bonus);
        } else {
            cin >> ammo >> wear;
            gun = new Sniper(type, ammo, wear);
        }

        guns.push_back(gun);
    }

    int shoot_time;
    cin >> shoot_time;

    for (auto gun : guns) {
        float total_damage = gun->total_damage(shoot_time);
        cout << gun->get_name() << ": " << total_damage << endl;
    }

    return 0;
}

