      dot.style.top = (j - 2) + 'px';
      dot.style.display = displayGrid ? '' : 'none';
      greenDotContainer.appendChild(dot);
    }
  }
}

// Finds the nearest snap point for a given mouse position
// within snapThreshold distance
function findNearestSnapPoint(mousePos) {
  let nearestSnapPoint = { x: mousePos.x, y: mousePos.y };
  let minDist = Infinity;

  gridPoints.forEach(point => {
    const dist = Math.hypot(point.x - mousePos.x, point.y - mousePos.y);
    if (dist < minDist && dist <= snapThreshold) {
      minDist = dist;
      nearestSnapPoint = point;
    }
  });

  return nearestSnapPoint;
}

