  new Edge(2, 3),
  new Edge(3, 0),
  new Edge(0, 4),
  new Edge(1, 5),
  new Edge(2, 6),
  new Edge(3, 7),
  new Edge(4, 5),
  new Edge(5, 6),
  new Edge(6, 7),
