    while (current) {
        Node* temp = head;
        bool done = false;
        while (temp != current && !done) {
            if (temp->surname.compare(current->surname) > 0) {
                previous->next = current->next;
                current->next = temp;
                if (temp == head) {
                    head = current;
                } else {
                    Node* temp2 = head;
                    while (temp2->next != temp) {
                        temp2 = temp2->next;
                    }
                    temp2->next = current;
                }
                done = true;
            }
            temp = temp->next;
            ++iterations;
        }
        if (!done) {
            previous = current;
            current = current->next;
        } else {
            current = previous->next;
        }
