__global__ void bitonicSortKernel(int *mat, int numStages, int numPasses)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int offset = idx * COLS;
    int temp;

    for (int stage = 0; stage < numStages; stage++)
    {
        for (int pass = 0; pass < numPasses; pass++)
        {
            int dist = 1 << (stage - pass);
            int compIdx = idx ^ dist;

            if (compIdx > idx && idx / (2 * dist) == compIdx / (2 * dist))
            {
                bool dir = ((idx & (1 << stage)) != 0);
                int val1 = mat[offset + idx];
                int val2 = mat[offset + compIdx];

                if ((dir && val1 > val2) || (!dir && val1 < val2))
                {
                    temp = val1;
                    mat[offset + idx] = val2;
                    mat[offset + compIdx] = temp;
                }
            }
        }
        __syncthreads();
    }
}

bool isSorted(int* data, int size) {
  for (int i = 0; i < size - 1; i++) {
    if (data[i] > data[i + 1])
      return false;
  }
  return true;
}

int main(int argc, char **argv)
{
    printf("%s Starting…\n", argv[0]);

    int *mat;

    mat = (int *)malloc(sizeof(int) * ROWS * COLS);

    // Read the input data from file
    FILE* inputFile = fopen("/content/datSeq1M.bin", "rb");
    fseek(inputFile, sizeof(int), SEEK_SET); // Skip the first integer
    fread(mat, sizeof(int), ROWS * COLS, inputFile);
    fclose(inputFile);

    int *mat_device;
    CHECK(cudaMalloc((void**)&mat_device, sizeof(int) * ROWS * COLS));
    CHECK(cudaMemcpy(mat_device, mat, sizeof(int) * ROWS * COLS, cudaMemcpyHostToDevice));

    int numStages = (int)(log2((float)COLS));
    int numPasses = numStages;

    dim3 grid(ROWS / COLS, 1, 1);
    dim3 block(COLS, 1, 1);

    bitonicSortKernel<<<grid, block>>>(mat_device, numStages, numPasses);
    CHECK (cudaDeviceSynchronize ());
    CHECK (cudaGetLastError ());

    CHECK(cudaMemcpy(mat, mat_device, sizeof(int) * ROWS * COLS, cudaMemcpyDeviceToHost));
    CHECK(cudaFree(mat_device));
    // Print the sorted data
    for (int i = 0; i < 20; i++) {
      printf("%d ", mat[i]);
      if( i == 10 ) break;
    }
    printf("\n");
    // Check if the array is sorted
    bool isOrdered = isSorted(mat, ROWS * COLS);

    // Print the result of the ordering check
    if (isOrdered) {
      printf("The array is ordered.\n");
    } else {
      printf("The array is not ordered.\n");
    }

    free(mat);
    return 0;
}
