const addNewUser = async (userData) => {
  try {
    const { email, password, name, age } = userData;

    // Create a new user with email and password using Firebase Authentication
    const userCredential = await firebase.auth().createUserWithEmailAndPassword(email, password);

    // Get the UID of the newly created user
    const uid = userCredential.user.uid;

    // Add the user's name and age to the database under their UID
    await firebase.database().ref(`users/${uid}`).set({
      name,
      age
    });

    console.log(`Successfully added user ${name} to the database!`);

  } catch (error) {
    console.error(error);
  }
}

// Call the function with the user data you want to add
