  int index = threadIdx.x + blockIdx.x * blockDim.x;
  int base = (index / length) * length;
  int target = index + step;

  while (values[index] > values[target]) {
    int tmp = values[index];
    values[index] = values[target];
    values[target] = tmp;
  }
}

