{
    // Clean up resources, if necessary
    // (depending on how Mesh and Material resources are managed)
    if (material) {
        material->Cleanup();
        delete material;
        material = nullptr;
    }

    if (mesh) {
        delete mesh;
        mesh = nullptr;
