```cpp
VkDescriptorPool CreateDescriptorPool(uint32_t maxSets, uint32_t uniformBufferCount, uint32_t combinedSamplerCount);
```

In Renderer.cpp, update the CreateDescriptorPool implementation:

```cpp
VkDescriptorPool Renderer::CreateDescriptorPool(uint32_t maxSets, uint32_t uniformBufferCount, uint32_t combinedSamplerCount) {
    std::array<VkDescriptorPoolSize, 2> poolSizes{};
    poolSizes[0].type = VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
    poolSizes[0].descriptorCount = uniformBufferCount;
    poolSizes[1].type = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    poolSizes[1].descriptorCount = combinedSamplerCount;

    VkDescriptorPoolCreateInfo poolInfo{};
    poolInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
    poolInfo.poolSizeCount = static_cast<uint32_t>(poolSizes.size());
    poolInfo.pPoolSizes = poolSizes.data();
    poolInfo.maxSets = maxSets;

    VkDescriptorPool descriptorPool;
    if (vkCreateDescriptorPool(device, &poolInfo, nullptr, &descriptorPool) != VK_SUCCESS) {
        throw std::runtime_error("Failed to create descriptor pool!");
    }
    return descriptorPool;
}
```

In the Scene.cpp or wherever you create your descriptor pool, make sure to change the CreateDescriptorPool call to pass the desired values:

```cpp
// Change the values depending on your specific needs
uint32_t maxSets = kMaxFramesInFlight * N; // N is the number of descriptor sets you expect per frame
