    new Person ("Joe", 30),
    new Person("Jane", 27)
};

List<Person> people2 = new List<Person>
{
    new Person("John", 25),
    new Person ("Joe", 30),
    new Person("Jane", 33)
};

var samePeople = people1.Intersect(people2, new PersonComparer()).ToList();

foreach(var p in samePeople)
{
    Console.WriteLine($"{p.Name}, {p.Age}");
}
```
In this example, we are comparing two lists of `Person` objects and finding the common `Person` objects that exist in both lists, using the `Intersect()` method. 

We pass an instance of our `PersonComparer` class as the second argument to the `Intersect()` method. This will use our custom `Equals()` method to determine if two instances of `Person` objects are equal or not.

