1. I2C 同步传输接口

i2c_transfer 函数是 I2C 的同步传输接口，该函数通过传入一个 i2c_msg 结构体数组来实现 I2C 数据传输。在函数参数中可以指定 I2C 设备地址，读写操作等参数，函数返回值用于表示传输是否成功。使用 i2c_transfer 函数时，当前线程会在函数返回前阻塞等待数据传输完成。

以下是一个 i2c_transfer 接口的使用示例：

```c
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <string.h>

#define I2C_SLAVE_ADDRESS 0x27

int main(int argc, char *argv[])
{
    int fd, ret;
    char write_buf[2] = {0x00, 0x01};
    char read_buf[2] = {};
    struct i2c_msg msgs[2];

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl");
        return -1;
    }

    msgs[0].addr = I2C_SLAVE_ADDRESS;
    msgs[0].flags = 0;           /* write */
    msgs[0].len = sizeof(write_buf);
    msgs[0].buf = write_buf;

    msgs[1].addr = I2C_SLAVE_ADDRESS;
    msgs[1].flags = I2C_M_RD;    /* read */
    msgs[1].len = sizeof(read_buf);
    msgs[1].buf = read_buf;

    ret = i2c_transfer(fd, msgs, 2);
    if (ret < 0) {
