private Bitmap GetBitmapFromMat(Mat mat)
{
    int bytesPerPixel = mat.NumberOfChannels * mat.ElementSize; // Image width in bytes
    int byteWidth = mat.Width * bytesPerPixel;
    Bitmap bitmap = new Bitmap(mat.Width, mat.Height, byteWidth, PixelFormat.Format24bppRgb, mat.DataPointer);
    return bitmap;
}
