			int pos;
			pos = line.find(", ");
				user.id = stoi(line.substr(0, pos));
			if (used_ids.find(user.id) != used_ids.end()) {
				throw runtime_error("Duplicated user id : " + to_string(user.id));
			}
			used_ids.insert(user.id);
			line.erase(0, pos + 1);
			pos = line.find(", ");
