using UnityEngine;
using Zenject;

public class CollidersSpawnerFireExtinguisher : MonoBehaviour
{
    [SerializeField]
    private FireExtinguisher[] collidersToSpawn;

    [SerializeField]
    private FireExtinguisherBoxTrigger[] colliders;

    [Inject]
    private ISubscriber subscriber = null;

    private void Start()
    {
        SubscribeToStartSessionMessage();
    }

    private void SubscribeToStartSessionMessage()
    {
        subscriber.Subscribe<StartSessionMessage>(SpawnColliders);
    }

    private void SpawnColliders(StartSessionMessage message)
    {
        UpdateCollidersPositions();
    }

    private void UpdateCollidersPositions()
    {
        for (int i = 0; i < collidersToSpawn.Length; i++)
        {
            colliders[i].transform.position = collidersToSpawn[i].gameObject.transform.position;
        }
    }

    private void OnEnable()
    {
        UnsubscribeFromStartSessionMessage();
    }

    private void UnsubscribeFromStartSessionMessage()
    {
        subscriber.Unsubscribe<StartSessionMessage>(SpawnColliders);
    }
}
