                    player.setY((int) (y + height));
                    player.stopDown();
                }
                if (x - width < playerX) {
                    player.setX((int) (x - width));
                    player.stopLeft();
                }
                if (x + width > playerX) {
                    player.setX((int) (x + width));
                    player.stopRight();
                }
            }
        }
    }

}
