    {
        pDevice->Release();
        Cleanup();
        return 1;
    }

    hr = CreateTextureFromMemory(pDevice, pData, size);
    if (FAILED(hr))
    {
        pDevice->Release();
        Cleanup();
        return 1;
    }

    // 渲染代码

    // 清除资源
    pDevice->Release();
    Cleanup();
    return 0;
}
```

