#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ftw.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>

#define MAX_EXT 6
#define BUF_SIZE 1024

typedef struct {
    char *dst;
    char *ext_list[MAX_EXT];
    int ext_count;
    int cp;
} Options;

int process_entry(const char *src, const struct stat *sb, int flag, struct FTW *ftwbuf);

Options options;

int main(int argc, char *argv[]) {
    if (argc < 4) {
        printf("Usage: %s [source_dir] [destination_dir] [options] <extension list>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    options.dst = argv[2];
    options.ext_count = 0;

    for (int i = 3; i < argc; i++) {
        if (strcmp(argv[i], "-cp") == 0) {
            options.cp = 1;
        } else if (strcmp(argv[i], "-mv") == 0) {
            options.cp = 0;
        } else if (options.ext_count < MAX_EXT) {
            options.ext_list[options.ext_count++] = argv[i];
        } else {
            printf("Too many extensions provided.\n");
            exit(EXIT_FAILURE);
        }
    }

    if (nftw(argv[1], process_entry, 20, FTW_DEPTH | FTW_PHYS) == -1) {
        perror("nftw");
        exit(EXIT_FAILURE);
    }

    if (!options.cp) {
        if (rmdir(argv[1]) != 0) {
            perror("rmdir");
            exit(EXIT_FAILURE);
        }
    }

    exit(EXIT_SUCCESS);
}

int process_entry(const char *src, const struct stat *sb, int flag, struct FTW *ftwbuf) {
    char dst[PATH_MAX];
    snprintf(dst, PATH_MAX, "%s%s", options.dst, src + ftwbuf->base);

    int skip = -1;
    if (flag == FTW_F) {
        for (int i = 0; i < options.ext_count; i++) {
            char *ext = strrchr(src, '.');
            if (ext != NULL && strcmp(ext + 1, options.ext_list[i]) == 0) {
                skip = i;
                break;
            }
        }
    }

    if (skip != -1) {
        return 0;
    }

    if (flag == FTW_D) {
        if (mkdir(dst, sb->st_mode) != 0 && errno != EEXIST) {
            perror("mkdir");
            return -1;
        }
    } else if (flag == FTW_F) {
        int src_fd = open(src, O_RDONLY);
        if (src_fd == -1) {
            perror("open");
            return -1;
        }
        int dst_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, sb->st_mode);
        if (dst_fd == -1) {
            perror("open");
            close(src_fd);
            return -1;
        }
        char buf[BUF_SIZE];
        ssize_t n;

        while ((n = read(src_fd, buf, BUF_SIZE)) > 0) {
            if (write(dst_fd, buf, n) != n) {
                perror("write");
                close(src_fd);
                close(dst_fd);
                return -1;
            }
        }

        if (n == -1) {
            perror("read");
        }

        close(src_fd);
        close(dst_fd);

        if (!options.cp) {
            if (unlink(src) != 0) {
                perror("unlink");
                return -1;
            }
        }
    }
    return 0;
}
