bindableViews::property<int> y{4};
bindableViews::property<double> hypotenuse; // Represents the hypotenuse of a right triangle

// Binding: hypotenuse = sqrt(x^2 + y^2)
hypotenuse.set_binding([&] { return std::sqrt(x * x + y * y); }, [&](auto& prop, double value) {
    // Setter that calls request_change on the x property
    x.request_change(std::sqrt(value * value - y * y));
});

hypotenuse.request_change(5); // Requests hypotenuse to change to 5
```

