Here's a simple C# console Tic Tac Toe game:

```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        char[,] board = new char[3, 3];
        char player = 'X';
        int row, col;

        // initialize board
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                board[i, j] = '-';
            }
        }

        // game loop
        while (true)
        {
            Console.Clear();
            Draw(board);

            // get player input
            Console.WriteLine("Player {0}'s turn. Enter row and column (0-2, separated by space):", player);
            row = int.Parse(Console.ReadLine());
            col = int.Parse(Console.ReadLine());

            // check if cell is empty
            if (board[row, col] != '-')
            {
                Console.WriteLine("Cell is already occupied. Try again.");
                Console.ReadKey();
                continue;
            }

            // make move
            board[row, col] = player;

            // check for win condition
            if (CheckWin(board, player))
            {
                Draw(board);
                Console.WriteLine("Player {0} wins!", player);
                break;
            }

            // check for tie condition
            if (CheckTie(board))
            {
                Draw(board);
                Console.WriteLine("It's a tie!");
                break;
            }

            // switch player
            player = (player == 'X') ? 'O' : 'X';
        }

        Console.ReadKey();
    }

    static void Draw(char[,] board)
    {
        Console.WriteLine("  0 1 2");
        for (int i = 0; i < 3; i++)
        {
            Console.Write(i + " ");
            for (int j = 0; j < 3; j++)
            {
                Console.Write(board[i, j] + " ");
            }
            Console.WriteLine();
        }
    }

    static bool CheckWin(char[,] board, char player)
    {
        // check rows
        for (int i = 0; i < 3; i++)
        {
            if (board[i, 0] == player && board[i, 1] == player && board[i, 2] == player)
            {
                return true;
            }
        }

        // check columns
        for (int j = 0; j < 3; j++)
        {
            if (board[0, j] == player && board[1, j] == player && board[2, j] == player)
            {
                return true;
            }
        }

        // check diagonals
        if (board[0, 0] == player && board[1, 1] == player && board[2, 2] == player)
        {
            return true;
        }

        if (board[2, 0] == player && board[1, 1] == player && board[0, 2] == player)
        {
            return true;
        }

        return false;
    }

    static bool CheckTie(char[,] board)
    {
        for (int i = 0; i < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                if (board[i, j] == '-')
                {
                    return false;
                }
            }
        }
        return true;
    }
}
