#include <stdio.h>
#include <stdbool.h>
#include <string.h>

#define MAX_N 20

int n;
double rates[MAX_N][MAX_N], ratios[MAX_N][MAX_N];
int path[MAX_N][MAX_N][MAX_N];

bool find_arbitrage() {
    for (int k = 0; k < n; ++k) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (ratios[i][j] < ratios[i][k] * ratios[k][j]) {
                    ratios[i][j] = ratios[i][k] * ratios[k][j];
                    path[i][j][0] = k;
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            if (ratios[i][i] > 1.01) {
                memmove(path[i][i] + 1, path[i][i], sizeof(int) * (n - 1));
                path[i][i][1] = i;
                return true;
            }
        }
    }

    return false;
}

void print_arbitrage() {
    for (int i = 0; i < n; ++i) {
        if (ratios[i][i] > 1.01) {
            for (int j = 0; j < n && path[i][i][j] != i; ++j) {
                printf("%d ", path[i][i][j] + 1);
            }
            printf("%d\n", i + 1);
            break;
        }
    }
}

int main() {
    while (scanf("%d", &n) != EOF) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i != j) {
                    scanf("%lf", &rates[i][j]);
                    ratios[i][j] = rates[i][j];
                } else {
                    ratios[i][j] = 1.;
                }
                path[i][j][0] = i;
            }
        }

        if (find_arbitrage()) {
            print_arbitrage();
        } else {
            printf("no arbitrage sequence exists\n");
        }
    }
    return 0;
}
