#include <stdio.h>
#include <string.h>
#include <stdbool.h>

char digitPattern[][4] = {" _ ", "  |", "|_|", "   "};

bool matchPattern(int digit, char *input) {
    for (int i = 0; i < 3; i++) {
        if (input[i] != ' ' && input[i] != digitPattern[digit][i])
            return false;
    }
    return true;
}

void process_account(char account[][27])
{
    int digits[9] = {0};
    bool valid = false;
    bool ambiguous = false;

    for (int i = 0; i < 9; i++)
    {
        int candidates = 0;
        int candidate_digit = 0;
        for (int j = 0; j < 10; j++)
        {
            if (matchPattern(j, account[0] + i * 3) && matchPattern(j, account[1] + i * 3) &&
                matchPattern(j, account[2] + i * 3))
            {
                candidates++;
                candidate_digit = j;
            }
        }

        if (candidates == 0)
        {
            valid = false;
            break;
        }
        else if (candidates > 1)
        {
            ambiguous = true;
            break;
        }

        digits[i] = candidate_digit;
    }

    if (valid && !ambiguous)
    {
        int checksum = 0;
        for (int i = 0; i < 9; i++)
        {
            checksum += (i + 1) * digits[8 - i];
        }
        if (checksum % 11 != 0)
            valid = false;
    }

    if (ambiguous)
        printf("ambiguous");
    else if (!valid)
        printf("failure");
    else
    {
        for (int i = 8; i >= 0; i--)
            printf("%d", digits[i]);
    }
    printf("\n");
}

int main()
{
    int test_cases;
    scanf("%d", &test_cases);

    while (test_cases--)
    {
        char account[3][27];
        for (int i = 0; i < 3; i++)
        {
            getchar();
            for (int j = 0; j < 27; j++)
            {
                account[i][j] = getchar();
            }
        }
        process_account(account);
    }

    return 0;
}
```

