    int matrix1[ROWS][COLS];
    int matrix2[ROWS][COLS];
    int sum[ROWS][COLS];

    // Input matrix1
    cout << "Enter elements of matrix1:" << endl;
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            cin >> matrix1[i][j];
        }
    }

    // Input matrix2
