        return delayResponse(delayTime).thenApply(
            delay -> ResponseEntity.ok("http://localhost:8080/api/profile")
        );
    }

    private CompletableFuture<Void> delayResponse(int delayMillis) {
        CompletableFuture<Void> future = new CompletableFuture<>();
        if (delayMillis > 0) {
            // Execute the delay and complete the future in a separate non-blocking thread
            future.completeAsync(
