        while (i <= num2) {
            System.out.print(i + " ");
            i++;
        }
        System.out.println(); // new line

        // do-while loop
        System.out.print("Enter a final number: ");
        int num3 = scanner.nextInt();

        int j = 1;
        do {
            System.out.print(j + " ");
            j++;
        } while (j <= num3);
        System.out.println(); // new line

        scanner.close();
    }
}
```

