#include <mpi.h>
#include <omp.h>
#include <cstdlib>
#include <cstdio>
#include <ctime>
#define N 1000000000 // 蒙特卡洛模拟的总次数

// 判断一个点是否在圆内
int in_circle(double x, double y) {
    if (x*x + y * y <= 1)
        return 1;
    else
        return 0;
}

int main(int argc, char *argv[]) {
    int rank, size, thread_count;
    int count = 0, global_count = 0;
    double pi;
    double start_time, end_time, time_taken;
    double mpi_speedup, serial_time;

    srand(time(NULL)); // 随机数种子

    MPI_Init(&argc, &argv); // 初始化MPI
    MPI_Comm_rank(MPI_COMM_WORLD, &rank); // 获取当前进程的rank
    MPI_Comm_size(MPI_COMM_WORLD, &size); // 获取总的进程数

    thread_count = atoi(argv[1]); // 从命令行参数中获取线程数
    omp_set_num_threads(thread_count); // 设置OpenMP的线程数

    double x, y;

    start_time = MPI_Wtime(); // 记录开始时间

    // 循环计算每个进程需要计算的次数，并把计算结果累加到count中
    #pragma omp parallel for reduction(+:count)
    for (int i = rank; i < N; i += size) {
        x = (double)rand() / RAND_MAX; // 生成随机点的x坐标
        y = (double)rand() / RAND_MAX; // 生成随机点的y坐标
        count += in_circle(x, y); // 判断该点是否在圆内，若在则count++
    }

    MPI_Reduce(&count, &global_count, 1, MPI_INT, MPI_SUM, 0, MPI_COMM_WORLD); // 把count的值reduce到全局变量global_count中

    if (rank == 0) { // 只有rank为0的进程输出结果
        pi = (double)global_count / N * 4; // 计算估算的圆周率
        end_time = MPI_Wtime(); // 记录结束时间
        time_taken = end_time - start_time; // 计算总的时间
        serial_time = time_taken * size; // 串行程序的时间

        printf("MPI/OpenMP: # of trials = %14d, estimate of pi is %1.16f \nMPI/OpenMP wall time = %f seconds\n", N, pi, time_taken);
        printf("Serial wall time = %f seconds\n", serial_time);

        mpi_speedup = serial_time / time_taken; // 计算MPI并行程序的加速比
        printf("speedup = %f\n", mpi_speedup);
    }
    MPI_Finalize(); // 结束MPI操作
    return 0;
}

