```java
private final int REQUEST_CODE_ACTIVITY_RECOGNITION = 100;
private PendingIntent activityRecognitionPendingIntent;
private ActivityRecognitionClient activityRecognitionClient;

private void requestActivityUpdates() {
    if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACTIVITY_RECOGNITION) != PackageManager.PERMISSION_GRANTED) {
        ActivityCompat.requestPermissions(this, new String[]{Manifest.permission.ACTIVITY_RECOGNITION}, REQUEST_CODE_ACTIVITY_RECOGNITION);
        return;
    }

    activityRecognitionClient = new ActivityRecognitionClient(this);

    Intent intent = new Intent(this, ActivityRecognitionService.class);
    activityRecognitionPendingIntent = PendingIntent.getService(this, 0, intent, PendingIntent.FLAG_UPDATE_CURRENT);

    activityRecognitionClient.requestActivityUpdates(1000, activityRecognitionPendingIntent);
}

@Override
public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
    super.onRequestPermissionsResult(requestCode, permissions, grantResults);
    if (requestCode == REQUEST_CODE_ACTIVITY_RECOGNITION && grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
        requestActivityUpdates();
    }
    // Handle other permission results here
}
