4. Create the user schema in server/models/UserModel.js:

```javascript
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');

const Schema = mongoose.Schema;

const userSchema = new Schema({
  email: { type: String, required: true, unique: true, trim: true },
  password: { type: String, required: true, trim: true },
  username: { type: String, required: true, unique: true, trim: true },
  avatarimg: { type: String },
  firstname: { type: String, required: true, trim: true },
  lastname: { type: String, required: true, trim: true },
  phoneNumber: { type: String, trim: true },
  IPAdresses: { type: [String] },
  walletName: { type: String },
  walletID: { type: String },
  tasksDone: { type: Number, default: 0 },
  joinDate: { type: Date, default: new Date() },
});

userSchema.pre('save', function(next) {
  let user = this;
  if (!user.isModified('password')) return next();

  bcrypt.genSalt(10, (err, salt) => {
    if (err) return next(err);

    bcrypt.hash(user.password, salt, (err, hash) => {
      if (err) return next(err);

      user.password = hash;
      next();
    });
  });
});

const User = mongoose.model('User', userSchema);
module.exports = User;
```

5. Create the user routes in server/routes/userRoutes.js:

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

const User = require('../models/UserModel');
const router = express.Router();

router.post('/register', async (req, res) => {
  try {
    let newUser = new User(req.body);
    let savedUser = await newUser.save();
    res.json(savedUser);
  } catch (error) {
    res.status(400).json('Error: ' + error);
  }
});

router.post('/login', async (req, res) => {
  try {
    const user = await User.findOne({ $or: [{ email: req.body.usernameOrEmail }, { username: req.body.usernameOrEmail }] });
    if (!user) return res.status(400).json('Invalid email or username.');

    const validPassword = await bcrypt.compare(req.body.password, user.password);
    if (!validPassword) return res.status(400).json('Invalid password.');

    const token = jwt.sign({ _id: user._id }, process.env.JWT_SECRET || 'secret-key');
    res.header('auth-token', token).json(token);
  } catch (error) {
    res.status(400).json('Error: ' + error);
  }
});

router.get('/logout', (req, res) => {
  res.header('auth-token', '').json('Logged out.');
});

module.exports = router;
```

