void compareDwgFiles(const wchar_t* dwgFilePath1, const wchar_t* dwgFilePath2)
{
    Acad::ErrorStatus es;
    AcDbDatabase* db1 = new AcDbDatabase(false, true);
    AcDbDatabase* db2 = new AcDbDatabase(false, true);

    // read the first DWG file into db1
    es = acdbHostApplicationServices()->readDwgFile(dwgFilePath1, db1);
    if (es != Acad::eOk)
    {
        acutPrintf(_T("\Error reading DWG file %s.\n"), dwgFilePath1);
        return;
    }

    // read the second DWG file into db2
    es = acdbHostApplicationServices()->readDwgFile(dwgFilePath2, db2);
    if (es != Acad::eOk)
    {
        acutPrintf(_T("\Error reading DWG file %s.\n"), dwgFilePath2);
        return;
    }

    // compare the two databases
    acedGetAcadWinApp()->compareDatabases(db1, db2);

    // cleanup
    delete db1;
    delete db2;
}

int main()
{
    const wchar_t* dwgFilePath1 = L"C:\\path\\to\\file1.dwg";
    const wchar_t* dwgFilePath2 = L"C:\\path\\to\\file2.dwg";

    compareDwgFiles(dwgFilePath1, dwgFilePath2);

    return 0;
}
