public void GetDistanceOfDifferences(List<Difference> differences)
{
    // assume that the differences are polylines
    foreach(Difference difference in differences)
    {
        // select the entities that are different in the two files
        ObjectIdCollection ids1, ids2;
        ids1 = SelectEntitiesByIds(difference.Handle1);
        ids2 = SelectEntitiesByIds(difference.Handle2);

        // get the first polyline from the first set of entities
        Polyline pline1 = null;

