        {
            Entity ent = (Entity)id.GetObject(OpenMode.ForRead);
            if (ent is Polyline)
            {
                pline1 = ent as Polyline;
                break;
            }
        }

        // get the second polyline from the second set of entities
        Polyline pline2 = null;

        foreach (ObjectId id in ids2)
        {
            Entity ent = (Entity)id.GetObject(OpenMode.ForRead);
            if (ent is Polyline)
            {
                pline2 = ent as Polyline;
                break;
            }
        }

        // calculate the distance between the two polylines
        double distance = pline1.GetClosestPointTo(pline2.Bounds.Value.MinPoint, false).DistanceTo(pline2.GetClosestPointTo(pline1.Bounds.Value.MinPoint, false));

