Here is a very simplified and minimal version of the Go Fish game in Java:

```java
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

class Card {
    enum Rank { ACE, TWO, THREE, FOUR, FIVE, SIX, SEVEN, EIGHT, NINE, TEN, JACK, QUEEN, KING }

    private final Rank rank;

    Card(Rank rank) {
        this.rank = rank;
    }

    Rank getRank() {
        return rank;
    }

    @Override
    public String toString() {
        return rank.name();
    }
}

class Deck {
    private List<Card> cards;

    Deck() {
        cards = new ArrayList<>();
        for (Card.Rank rank : Card.Rank.values()) {
            cards.add(new Card(rank));
        }
    }

    void shuffle() {
        Collections.shuffle(cards);
    }

    Card dealCard() {
        return cards.isEmpty() ? null : cards.remove(cards.size() - 1);
    }
}

class Player {
    private String name;
    private List<Card> hand;

    Player(String name) {
        this.name = name;
        this.hand = new ArrayList<>();
    }

    void addCard(Card card) {
        if (card != null) {
            hand.add(card);
        }
    }

    boolean hasRank(Card.Rank rank) {
        return hand.stream().anyMatch(card -> card.getRank() == rank);
    }

    Card removeRank(Card.Rank rank) {
        for (Card card : hand) {
            if (card.getRank() == rank) {
                hand.remove(card);
                return card;
            }
        }
        return null;
    }

    boolean hasCards() {
        return !hand.isEmpty();
    }

    String getName() {
        return name;
    }
}

public class SimpleGoFish {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Welcome to Simple Go Fish!");

        System.out.print("Enter player 1's name: ");
        String player1Name = scanner.nextLine();

        System.out.print("Enter player 2's name: ");
        String player2Name = scanner.nextLine();

        Deck deck = new Deck();
        deck.shuffle();

        Player player1 = new Player(player1Name);
        Player player2 = new Player(player2Name);

        for (int i = 0; i < 7; i++) {
            player1.addCard(deck.dealCard());
            player2.addCard(deck.dealCard());
        }

        while (player1.hasCards() && player2.hasCards()) {
            Card.Rank[] ranks = Card.Rank.values();
            List<Card.Rank> rankList = new ArrayList<>(Arrays.asList(ranks));
            Collections.shuffle(rankList);

            for (Card.Rank rank : rankList) {
                if (player1.hasRank(rank) && player2.hasRank(rank)) {
                    player1.removeRank(rank);
                    player2.removeRank(rank);

                    System.out.println(player1.getName() + " and " + player2.getName() + " both had a " + rank + ".");
                }
            }

            player1.addCard(deck.dealCard());
            player2.addCard(deck.dealCard());
        }

        String winner = player1.hasCards() ? player1.getName() : player2.getName();
        System.out.println("Game over. " + winner + " wins!");
    }
}
```

