You can use async.queue and axios to insert data into MongoDB with Node.js by following these steps:

1. Install the required modules:

```
npm install async axios mongodb
```

2. Connect to MongoDB:

```javascript
const MongoClient = require('mongodb').MongoClient;

const url = 'mongodb://localhost:27017/mydb';

MongoClient.connect(url, function(err, db) {
  if (err) throw err;
  console.log('Connected to MongoDB!');

  // Use the db object to interact with the database
});
```

3. Create a queue:

```javascript
const async = require('async');

const queue = async.queue(function(task, callback) {
  axios.post('https://my-api.com', task.data)
    .then(function(response) {
      console.log(response.data);

      // Insert data into MongoDB
      db.collection('mycollection').insertOne(task.data, function(err, res) {
        if (err) throw err;
        console.log('Data inserted into MongoDB!');
        callback();
      });
    })
    .catch(function(error) {
      console.log(error);
      callback(error);
    });
}, 10); // Set concurrency to 10

queue.drain(function() {
  console.log('All tasks have been processed!');
});
```

4. Add tasks to the queue:

```javascript
queue.push({ data: { name: 'John', age: 30 } });
queue.push({ data: { name: 'Alice', age: 25 } });
queue.push({ data: { name: 'Bob', age: 40 } });
``` 

This will add three tasks to the queue that will be processed asynchronously, with a maximum concurrency of 10. Each task will send a POST request to the specified API with some data, and then insert that data into the specified MongoDB collection. Once all tasks have been processed, the 'All tasks have been processed!' message will be displayed.

