```javascript
// Import required modules
const axios = require('axios');
const async = require('async');
const MongoClient = require('mongodb').MongoClient;

// MongoDB connection URL
const url = 'mongodb://localhost:27017/mydb';

// Create a MongoClient object and connect to MongoDB
const client = new MongoClient(url, { useNewUrlParser: true });

client.connect(function(err) {
  if (err) throw err;

  console.log('Connected successfully to MongoDB!');

  // Get a reference to the MongoDB collection
  const collection = client.db().collection('mycollection');

  // Create an array to store the results of Axios requests
  const results = [];

  // Create an async queue with concurrency of 5
  const queue = async.queue(function(task, callback) {
    // Make a POST request using Axios
    axios.post('https://my-api.com', task.data)
      .then(function(response) {
        results.push(response.data);
        callback();
      })
      .catch(function(error) {
        console.log(error);
        callback(error);
      });
  }, 5);

  // Push data to the async queue
  queue.push({ data: { name: 'John', age: 30 } });
  queue.push({ data: { name: 'Alice', age: 25 } });
  queue.push({ data: { name: 'Bob', age: 40 } });

  // When the async queue has finished processing all items, insert the results into MongoDB
  queue.drain(function() {
    console.log('All items have been processed!');
    console.log(`Results: ${JSON.stringify(results)}`);

    // Insert the results into MongoDB
    collection.insertMany(results)
      .then(function() {
        console.log(`Results inserted successfully into MongoDB!`);
        client.close();
      })
      .catch(function(error) {
        console.log(error);
        client.close();
      });
  });
});
```

In this code, we create an array called `results` that will store the responses from Axios. We then create an async queue with a concurrency limit of 5, and push data to the queue using the `queue.push()` method.

As each item in the queue is processed by Axios, the data is pushed to the `results` array. Once all items in the queue have been processed, the `queue.drain()` event is fired, and we can then insert the `results` array into MongoDB using `insertMany()`.

Note that we call `client.close()` once we have finished inserting the results into MongoDB. This is important to ensure that the connection to MongoDB is properly closed.

To write an async queue in an async way, you can use the `async` module's `async.eachSeries` method to iterate through an array of items, and perform the asynchronous operation on each item.

Here's an example of how you could use `async.eachSeries` to insert data into MongoDB:

```javascript
// Import required modules
const axios = require('axios');
const async = require('async');
const MongoClient = require('mongodb').MongoClient;

// MongoDB connection URL
const url = 'mongodb://localhost:27017/mydb';

// Create a MongoClient object and connect to MongoDB
const client = new MongoClient(url, { useNewUrlParser: true });

client.connect(async function(err) {
  if (err) throw err;

  console.log('Connected successfully to MongoDB!');

  // Get a reference to the MongoDB collection
  const collection = client.db().collection('mycollection');

  // Create an array of data objects to insert into MongoDB
  const data = [
    { name: 'John', age: 30 },
    { name: 'Alice', age: 25 },
    { name: 'Bob', age: 40 }
  ];

  try {
    // Iterate through the array of data objects and perform the async operation
    await async.eachSeries(data, async function(item) {
      // Make a POST request using Axios
      const response = await axios.post('https://my-api.com', item);

      // Insert the data into the MongoDB collection
      await collection.insertOne(response.data);

      console.log(`Data inserted successfully into MongoDB: ${JSON.stringify(response.data)}`);
    });

    console.log('All data inserted into MongoDB!');
    client.close();
  } catch (err) {
    console.log(err);
    client.close();
  }
});
```

In this code, we create an array of data objects that we want to insert into MongoDB. We then use `async.eachSeries` to iterate through each data object in the array.

On each iteration, we make a POST request using Axios to a target API endpoint with the current data object. We then insert the returned data into the specified MongoDB collection using `insertOne()`.

Note that we need to use `await` with each asynchronous operation to wait for its completion before moving on to the next item in the array. This ensures that each operation is performed in the correct order.

Once all items in the array have been processed, we log a message to the console and close the MongoDB connection using `client.close()`.

