```js
function search(query = '', role = '', city = '', genre = '', callback) {
  const searchByNameAndGenre = `
  SELECT * FROM users
  WHERE (LOWER(name) LIKE ? OR LOWER(genre) LIKE ?)
    AND (? = '' OR LOWER(role) = LOWER(?))
    AND (? = '' OR LOWER(city) = LOWER(?))
    AND (? = '' OR LOWER(genre) = LOWER(?))
  `;

  const searchQuery = query ? '%' + query.toLowerCase() + '%' : '%';
  const params = [searchQuery, searchQuery, role, role, city, city, genre, genre];

  connection.query(searchByNameAndGenre, params, (err, rows) => {
    if (err) {
      console.error("Ошибка при выполнении поиска с параметрами: ", query, role, city, genre, err);
      callback(err);
    }
    else {
      const musicians = rows.map(musician => {
        return {
          name: musician.name,
          genre: musician.genre,
          originalName: musician.name,
          profileLink: `/profile/${musician.id}`,
          thumbnail: musician.thumbnail,
          soundcloud: musician.soundcloud,
          role: musician.role,
          city: musician.city
        };
      });
      callback(null, musicians);
    }
  });
}
